/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A25 frozen manifest: disciplinary–disenchantment (80 headwords), hand-authored. */
'use strict';
const D = globalThis.RA.D;
const Q = (w,n,s,p,a,b,c,x,type='meaning') => ({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:type,type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M = (wrong,right,reason,type='meaning') => ({errorType:type,wrong,right,reason});
const C = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E = (origin,w) => ({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`});
const P = (w,origin,ctx,mistake,quiz) => D(w,{etymology:E(origin,w),contexts:[ctx],mistakes:[mistake],quiz});

P('disciplinary','disciplinary 由 discipline 加 -ary 构成；discipline 经法语来自拉丁语 disciplina“教学、训练”，现代可指纪律处分相关的，也可指学科领域的。',C('disciplinary.s1','学校管理','After the lab safety breach, the dean opened a disciplinary review and gave the student a chance to explain what had happened.','实验室安全违规后，院长启动了纪律审查，并给学生机会说明情况。','After the lab safety breach / the dean opened a disciplinary review / and gave the student a chance to explain what had happened.','disciplinary 修饰 review；disciplinary action/proceedings 常指纪律处分或程序。','违规后启动审查、听取解释，符合纪律管理义 s1。'),M('The disciplinary hearing was held to reward the student for breaking the safety rules.','The disciplinary hearing was held to determine consequences for the safety-rule violation.','disciplinary hearing 调查违规并决定后果，不是奖励违规行为。'),[Q('disciplinary',1,1,'A disciplinary hearing at a school deals with?','a possible breach of rules','choosing next year’s textbooks','planning a sports festival','纪律听证处理违反校规的事项。'),Q('disciplinary',2,2,'A disciplinary approach in an academic course concerns?','a field or branch of study','a student’s punishment','a building’s fire alarm','该词也可指学科领域，如 disciplinary approach。'),Q('disciplinary',3,1,'Which phrase most clearly refers to penalties for misconduct?','disciplinary action','disciplinary boundary between chemistry and physics','disciplinary reading list','misconduct 后的 action 是纪律处分。'),Q('disciplinary',4,1,'A coach opens a disciplinary inquiry after a player cheats. The inquiry is?','about enforcing team rules','about choosing team colors','about repairing the field','调查作弊与执行队规相关。')]);
P('disciplined','disciplined 是 discipline 的过去分词形容词，源自拉丁语 disciplina“训练、学习”；描述自控、守序，或受正式处分。',C('disciplined.s1','学习习惯','A disciplined reader studies for thirty minutes each morning, even when a more entertaining option is available.','自律的读者每天早晨学习三十分钟，即使有更有趣的选择也如此。','A disciplined reader studies for thirty minutes each morning / even when a more entertaining option is available.','disciplined 作定语形容词；even when 引出让步情境。','能持续按计划学习体现自控与训练有素。'),M('Although she followed no schedule and abandoned every task, the report called her highly disciplined.','Although she followed no schedule and abandoned every task, the report called her highly disorganized.','没有计划且放弃任务体现无条理，和 disciplined 的自律义相反。'),[Q('disciplined',1,1,'A disciplined worker is most likely to?','follow a plan consistently','ignore every deadline','change goals every few minutes','disciplined 强调自控并持续按计划行动。'),Q('disciplined',2,1,'Which habit shows a disciplined approach to practice?','repeating a difficult exercise on a regular schedule','practising only when someone offers a prize','skipping every review session','规律坚持练习体现自律。'),Q('disciplined',3,1,'In “a disciplined response,” disciplined suggests the response is?','controlled rather than impulsive','unrelated to the issue','loud regardless of context','自控的回应不是冲动反应。'),Q('disciplined',4,1,'A student who keeps careful notes and submits work on time is?','disciplined','careless','indifferent','按时完成并认真记录显示自律。')]);
P('disclaimer','disclaimer 由 disclaim + -er 构成；disclaim 表示否认或声明不承担某项责任，disclaimer 现代常指限制责任或用途的声明；不在此推断更早词源。',C('disclaimer.s1','法律与出版','The report begins with a disclaimer stating that its figures are estimates and should not be treated as individual financial advice.','报告开头有一则免责声明，说明数据只是估算，不应视为个人财务建议。','The report begins with a disclaimer / stating that its figures are estimates / and should not be treated as individual financial advice.','disclaimer 是可数名词；stating 分词短语说明声明内容。','该声明限定读者如何依赖报告并划清责任，符合 s1。'),M('The disclaimer promised that the publisher accepted unlimited liability for every reader’s losses.','The disclaimer stated that the publisher did not accept liability for every reader’s losses.','disclaimer 通常用于说明限制或排除责任；“承诺无限责任”与其功能相反。'),[Q('disclaimer',1,1,'A legal disclaimer is usually included to?','state a limit on responsibility','guarantee a particular profit','list every employee’s duties','免责声明说明责任范围或限制。'),Q('disclaimer',2,1,'A website says its comments are users’ opinions, not medical advice. This is a?','disclaimer','receipt','prescription','这句限定内容用途与责任，属于免责声明。'),Q('disclaimer',3,1,'Where would a reader most likely find a disclaimer?','near the beginning or end of a report','inside a list of ingredients only','on a road map legend for elevation','免责声明常放在报告或网站说明处。'),Q('disclaimer',4,1,'The noun disclaimer is related to the verb?','disclaim','disclose','discolor','disclaimer 表示作出否认或责任限定的声明。')]);
P('discoloration','discoloration 由 dis-、color 和 -ation 构成，字面指颜色改变；美式拼写用 -or，英式常见 discolouration。',C('discoloration.s1','材料维护','The conservator noticed a brown discoloration along the edge of the painting and kept the frame away from direct sunlight.','修复师注意到画作边缘有一片褐色变色，便将画框移离直射阳光。','The conservator noticed a brown discoloration along the edge of the painting / and kept the frame away from direct sunlight.','discoloration 可数时指一处变色或污斑；notice + 名词 + 介词短语。','褐色斑块是表面非预期颜色变化，符合 s1。'),M('The white fabric showed no discoloration, but a large yellow stain had appeared across it.','The white fabric showed discoloration: a large yellow stain had appeared across it.','明显黄斑就是 discoloration；说 no discoloration 与后文冲突。'),[Q('discoloration',1,1,'A discoloration on a white shirt is?','an unwanted change or mark in its color','a clean, unchanged area','a tear in the fabric','discoloration 指颜色出现变化或污斑。'),Q('discoloration',2,1,'What could cause discoloration on old paper?','light or chemical exposure changing its color','folding the paper neatly','reading the printed words','光照或化学反应会使纸张变色。'),Q('discoloration',3,1,'A dentist checks a tooth for discoloration to see whether it?','has changed shade','has become taller','can hear sounds','牙齿颜色改变即 discoloration。'),Q('discoloration',4,1,'The British spelling corresponding to discoloration is commonly?','discolouration','discolour','discolorful','英式拼写通常保留 colour 中的 u。')]);
P('discomfit','discomfit 源自古法语 desconfit，最终与拉丁语 dis- + conficere“彻底击败”有关；现代主要指使人窘迫或不安。',C('discomfit.s1','社交互动','The unexpected question about her private finances seemed to discomfit the candidate, who paused before asking to move on.','关于私人财务的意外提问似乎让候选人窘迫不安；她停顿片刻后请求换个话题。','The unexpected question about her private finances seemed to discomfit the candidate / who paused / before asking to move on.','discomfit 是及物动词；seem to + 动词原形，关系从句修饰 candidate。','私人问题使候选人不自在，符合现代常用义。'),M('The intrusive question discomfited him, so he answered with complete ease and no hesitation.','The intrusive question did not discomfit him, so he answered with complete ease and no hesitation.','若他回答毫无不适，原句的 discomfited 与结果矛盾，应加否定。'),[Q('discomfit',1,1,'If a remark discomfits someone, it makes that person feel?','awkward or uneasy','physically taller','certain of a fact','discomfit 指使人窘迫、不安。'),Q('discomfit',2,1,'Which question is most likely to discomfit a guest?','an unexpected personal question in front of a crowd','a clear question about the train time','a polite offer of tea','当众被意外追问隐私容易使人尴尬。'),Q('discomfit',3,1,'Choose the closest meaning: “The silence discomfited her.”','The silence made her uneasy.','The silence helped her fall asleep.','The silence proved her right.','句意是沉默令她不自在。'),Q('discomfit',4,1,'Which situation does NOT discomfit a speaker?','the audience listens calmly to a familiar topic','the microphone fails during an important answer','a colleague asks an embarrassing question','熟悉话题且听众平静，不太会使人窘迫。')]);
P('discomfort','discomfort 由 dis- 加 comfort 构成，comfort 经古法语源于拉丁语 confortare“加强”；可指身体轻微疼痛，也可指社交或心理不自在。',C('discomfort.s2','访谈与情绪','He expressed discomfort with the joke because it mocked a colleague who was not present to answer back.','他表示对这个笑话感到不自在，因为它嘲弄了一位不在场、无法回应的同事。','He expressed discomfort with the joke / because it mocked a colleague / who was not present to answer back.','discomfort with + 事物表示对某事不安；because 引原因。','不适源自对冒犯性玩笑的心理/社交不安，符合 s2。'),M('The chair caused no physical discomfort, yet she complained that it was painful to sit on.','The chair caused physical discomfort, and she complained that it was painful to sit on.','疼痛正是身体不适；“caused no discomfort”与投诉理由相冲突。'),[Q('discomfort',1,1,'Physical discomfort is?','mild pain or bodily unease','a strong feeling of joy','a permanent loss of memory','身体义 discomfort 指轻微疼痛或不适。'),Q('discomfort',2,2,'A guest feels discomfort during a hostile conversation. The feeling is?','mental or social unease','a broken bone','a pleasant surprise','敌意谈话带来的是心理社交上的不自在。'),Q('discomfort',3,1,'A tight shoe may cause?','discomfort in the foot','a disclaimer','disenchantment with a book','鞋子过紧会造成脚部不适。'),Q('discomfort',4,1,'Which phrase is natural?','express discomfort with a remark','express discomfort at a dictionary only','discomfort for the answer meaning “enjoy”','常用结构 express discomfort with。')]);
P('discompose','discompose 由 dis- 与 compose 构成；compose 经法语源自拉丁语 componere“放在一起、安排”，discompose 即扰乱平静。',C('discompose.s1','公开发言','A hostile interruption did not discompose the speaker; she waited for the room to settle and then finished her point.','恶意打断并未扰乱演讲者的镇定；她等会场安静下来后继续讲完观点。','A hostile interruption did not discompose the speaker / she waited for the room to settle / and then finished her point.','discompose 是及物动词；did not 后接动词原形。','是否保持镇静正是该词描述的心理状态。'),M('The sudden accusation discomposed her, so she remained perfectly calm and showed no sign of disturbance.','The sudden accusation did not discompose her, so she remained perfectly calm and showed no sign of disturbance.','保持镇定、毫无扰动说明 accusation 未使她不安，需补否定。'),[Q('discompose',1,1,'To discompose a person is to?','disturb that person’s composure','make that person younger','organize that person’s schedule','discompose 指扰乱平静、使人不安。'),Q('discompose',2,1,'A calm pianist is discomposed when?','an unexpected alarm makes her lose focus','she plays a familiar opening','the audience applauds politely','意外警报使她失去镇定，体现 discompose。'),Q('discompose',3,1,'Which verb is closest to discompose in this context: “The news discomposed him”?','unsettled','reassured','decorated','消息令他不安，即 unsettled。'),Q('discompose',4,1,'If nothing discomposes a negotiator, the negotiator?','keeps composure under pressure','forgets every agreement','cannot hear the other side','不受扰乱表示能在压力下保持镇定。')]);
P('disconcert','disconcert 经古法语 desconcerter 进入英语，与 concert 的协调、和谐义相关；现代动词指使人困惑或不自在，不强拆更早词源。',C('disconcert.s1','面试情境','The panel’s sudden switch to questions in another language seemed to disconcert the applicant, who asked for a moment to think.','评审团突然改用另一种语言提问，似乎让申请者不知所措；她请求先思考片刻。','The panel’s sudden switch to questions in another language / seemed to disconcert the applicant / who asked for a moment to think.','disconcert 是及物动词；seem to 后接动词原形。','意外变化令申请者困惑不安，符合该词义。'),M('The confusing announcement disconcerted the audience, leaving everyone entirely clear about what to do.','The confusing announcement disconcerted the audience, leaving everyone unsure about what to do.','令人困惑的公告通常使人不确定；“entirely clear”与 disconcert 的结果冲突。'),[Q('disconcert',1,1,'A confusing interruption may disconcert a speaker by making the speaker?','lose confidence or feel unsure','feel fully prepared','forget how to read','disconcert 指使人困惑、不安。'),Q('disconcert',2,1,'Which event would most likely disconcert a new employee?','being unexpectedly asked to lead a meeting','receiving a clear schedule in advance','being shown the office kitchen','突如其来的主持任务可能让新人不知所措。'),Q('disconcert',3,1,'Complete the meaning: “The odd silence disconcerted us.” It?','made us feel unsure','made us stronger','gave us a clear map','句意是古怪的沉默使我们感到不安/疑惑。'),Q('disconcert',4,1,'If a question disconcerts a witness, the witness may?','hesitate because it is unsettling','answer with perfect ease','leave the courtroom permanently by definition','令人不安的问题可能使证人迟疑。')]);
P('disconnect','disconnect 由 dis-“分开”与 connect“连接”构成；connect 源自拉丁语 connectere“系在一起”，既可指切断实体/网络连接，也可指情感疏离。',C('disconnect.s1','网络设备','Before replacing the router, disconnect it from the power outlet and wait until every indicator light has gone dark.','更换路由器前，先拔掉电源插头，等所有指示灯熄灭。','Before replacing the router / disconnect it from the power outlet / and wait until every indicator light has gone dark.','disconnect A from B 表示把 A 与 B 断开；祈使句用动词原形。','从插座拔下设备是切断实体电源连接的 s1。'),M('The technician disconnected the cable from the socket, so the device remained connected to mains power.','The technician disconnected the cable from the socket, so the device was no longer connected to mains power.','拔掉电缆会切断电源；“仍连接主电源”与前因不符。'),[Q('disconnect',1,1,'To disconnect a lamp from the outlet is to?','break its electrical connection','make it brighter','measure its weight','disconnect from outlet 即切断电源连接。'),Q('disconnect',2,2,'A manager feels disconnected from the team when?','communication and shared understanding have weakened','all members exchange ideas openly','the team celebrates a shared success','情感义指缺少联系或理解。'),Q('disconnect',3,1,'Before cleaning a powered appliance, you should usually?','disconnect it from its power source','cover its switch with water','increase its voltage','清洁前切断电源可避免触电风险。'),Q('disconnect',4,1,'Which pairing is idiomatic?','disconnect the battery from the circuit','disconnect the battery at the circuit it','disconnect about the battery circuit','常见结构是 disconnect A from B。')]);
P('disconnected','disconnected 是 disconnect 的过去分词形容词，可描述设备未连接，也可描述论述、段落之间缺乏逻辑衔接。',C('disconnected.s2','文章结构','The report felt disconnected: its opening described coastal erosion, but the next section jumped without explanation to school funding.','报告读起来缺乏连贯性：开头谈海岸侵蚀，下一节却毫无解释地跳到学校经费。','The report felt disconnected / its opening described coastal erosion / but the next section jumped without explanation to school funding.','disconnected 可作表语形容词；冒号后解释判断原因。','两个主题之间没有逻辑过渡，符合 s2。'),M('The chapter was disconnected because every paragraph followed clearly from the one before it.','The chapter was coherent because every paragraph followed clearly from the one before it.','段落之间清晰衔接说明连贯，不是 disconnected。'),[Q('disconnected',1,1,'A disconnected charger is?','not joined to a power supply','fully plugged into the wall','charged to one hundred percent','实体义是未与电源连接。'),Q('disconnected',2,2,'A disconnected argument has?','ideas with weak or missing logical links','a clear progression of reasons','one carefully stated conclusion','论述义指思路不连贯。'),Q('disconnected',3,1,'Which clue suggests that a paragraph is disconnected?','it suddenly changes topic without a transition','each sentence supports the same point','the conclusion follows from the evidence','突然跳题说明缺少逻辑衔接。'),Q('disconnected',4,1,'The closest opposite of disconnected writing is?','coherent','unrelated','fragmented','coherent 表示连贯，和 disconnected 相反。')]);
P('discontent','discontent 由 dis- 与 content“满足”构成；content 经古法语源自拉丁语 contentus“满意的”，discontent 指对现状不满或不满情绪。',C('discontent.s1','职场沟通','Growing discontent among night-shift staff followed the pay freeze, and several workers asked management to explain the decision.','冻结工资后，夜班员工的不满情绪日渐增加，几名员工要求管理层解释决定。','Growing discontent among night-shift staff followed the pay freeze / and several workers asked management to explain the decision.','discontent 常作不可数名词；among 表示情绪所在群体。','员工对工资决定不满并要求改变，体现 s1。'),M('The staff showed deep discontent with the pay freeze and said they were completely satisfied with it.','The staff showed deep contentment with the pay freeze and said they were completely satisfied with it.','完全满意对应 contentment，与 discontent 的不满相反。'),[Q('discontent',1,1,'Discontent with a policy means?','unhappiness and a wish for change','complete satisfaction with it','lack of knowledge about it','discontent 表示不满，常伴随希望改变。'),Q('discontent',2,1,'What may increase discontent among workers?','a pay freeze they consider unfair','a transparent bonus they welcome','a safer workplace they requested','被认为不公平的冻结工资会加剧不满。'),Q('discontent',3,1,'Choose a natural phrase.','public discontent with the decision','public discontent to the decision','public discontent at deciding it','常用搭配是 discontent with。'),Q('discontent',4,1,'A sign of discontent is that people?','voice complaints and call for reform','praise the arrangement without reservation','stop noticing the issue altogether','表达抱怨、要求改革体现不满。')]);
P('discontented','discontented 由 discontent 加 -ed 构成，表示对境况或结果不满意；content 的词源来自拉丁语 contentus“满意的”。',C('discontented.s1','消费者反馈','Several discontented passengers wrote to the rail company after the repeated cancellations left them stranded overnight.','多名不满的乘客在列车屡次取消、被迫滞留一夜后给铁路公司写信投诉。','Several discontented passengers wrote to the rail company / after the repeated cancellations left them stranded overnight.','discontented 修饰 passengers；leave + 宾语 + 形容词表示使……处于某状态。','乘客因取消班次而不满意，符合该词义。'),M('The discontented customer praised the delay and said every part of the service met her expectations.','The contented customer praised the service and said every part met her expectations.','赞扬服务并称其达到期望，表现满意；contented 才适合。'),[Q('discontented',1,1,'A discontented customer is?','unhappy with a product or service','fully pleased with every detail','unaware that a purchase occurred','discontented 指不满意的。'),Q('discontented',2,1,'Which passenger is discontented?','one who complains after a train is repeatedly cancelled','one who reaches the destination on time and praises the ride','one who has not yet bought a ticket','反复取消使乘客不满。'),Q('discontented',3,1,'The suffix -ed in discontented describes?','a person experiencing dissatisfaction','a future event','a plural group of objects','此处 -ed 形成描述感受状态的形容词。'),Q('discontented',4,1,'A discontented employee may ask for?','a change to an unsatisfactory condition','more of the same unfair treatment','nothing because all is ideal','不满意者可能要求改变不理想状况。')]);
P('discontinue','discontinue 由 dis-“停止”与 continue“继续”构成；continue 经古法语、拉丁语 continuare“连成一体”，本词可指停止活动或停售产品。',C('discontinue.s2','产品公告','The manufacturer will discontinue the older model in June but continue providing replacement parts for several years.','制造商将在六月停产旧型号，但仍会在数年内供应替换零件。','The manufacturer will discontinue the older model in June / but continue providing replacement parts / for several years.','discontinue 是及物动词；but 对比停产与继续售后。','停止生产某型号而保留配件供应，体现产品/做法终止义 s2。'),M('The publisher discontinued the series but released a new volume every month afterward.','The publisher continued the series and released a new volume every month afterward.','每月持续出版新卷说明系列未停止；应用 continued。'),[Q('discontinue',1,1,'A company discontinues a product when it?','stops making or selling it','raises its price temporarily','renames the factory','discontinue 可指产品停止生产或销售。'),Q('discontinue',2,1,'A school discontinues a weekly meeting if it?','ends the meeting as a regular practice','moves it to a different room once','adds another attendee','停止固定举行这项活动即 discontinue。'),Q('discontinue',3,1,'Which statement is consistent?','The service will discontinue in May and will no longer be offered.','The service is discontinued but runs every day unchanged.','The service discontinued and is being introduced for the first time.','停止服务意味着之后不再提供。'),Q('discontinue',4,1,'The opposite of discontinue in “discontinue treatment” is?','continue treatment','cancel treatment','postpone treatment indefinitely','continue 是 discontinue 的反义词。')]);
P('discontinuity','discontinuity 由 dis-、continuity 构成；continuity 源自拉丁语 continuus“连续的”，discontinuity 指连续过程中的间断或不衔接。',C('discontinuity.s1','地质观察','A sharp discontinuity in the rock layers marks a long period when erosion removed earlier deposits before newer layers formed.','岩层中明显的间断标示出一段漫长时期：侵蚀先移除了早期沉积物，之后才形成较新的岩层。','A sharp discontinuity in the rock layers / marks a long period / when erosion removed earlier deposits before newer layers formed.','discontinuity 作可数名词；when 从句解释间断发生的时期。','早期沉积与后来岩层之间有缺失段，符合连续性中断义。'),M('The sequence showed no discontinuity because a long missing interval separated its two stages.','The sequence showed a discontinuity because a long missing interval separated its two stages.','存在长时间缺失段正是 discontinuity，应肯定有间断。'),[Q('discontinuity',1,1,'A discontinuity in a process is?','a gap or break in its continuity','an uninterrupted sequence','a minor spelling variation','discontinuity 指过程不连续处或间隙。'),Q('discontinuity',2,1,'A sudden jump in a graph with no values between two regions shows?','a discontinuity','a smooth curve','a repeated pattern','图线上有跳跃、没有连续过渡，显示 discontinuity。'),Q('discontinuity',3,1,'Geologists may infer a discontinuity when?','a period of deposition is missing between rock layers','every layer formed without interruption','a rock has a different name','缺失沉积时段会形成地层间断。'),Q('discontinuity',4,1,'The closest opposite is?','continuity','interruption','gap','continuity 表示连续，与 discontinuity 相反。')]);
P('discouraging','discouraging 由 discourage + -ing 构成；discourage 是 dis- 加 courage，courage 源自拉丁语 cor“心”，本词可指令人泄气的，也可指劝阻某行动的。',C('discouraging.s1','求职与信心','The first rejection was discouraging, but Maya revised her application and continued applying to other laboratories.','第一次被拒令人泄气，但玛雅修改了申请，继续向其他实验室投递。','The first rejection was discouraging / but Maya revised her application / and continued applying to other laboratories.','discouraging 描述引发感受的事；-ing 形容事物令人产生某感受。','拒信降低信心但没有阻止她继续，符合令人泄气义。'),M('A discouraging result made the runner more hopeful about winning and eager to continue.','An encouraging result made the runner more hopeful about winning and eager to continue.','信心增强、更加期待通常是令人鼓舞的结果，不是令人泄气的结果。'),[Q('discouraging',1,1,'A discouraging result is one that?','makes someone less hopeful or confident','guarantees success','has no effect on anyone','discouraging 指令人气馁、降低信心的。'),Q('discouraging',2,2,'A sign discouraging parking is intended to?','persuade drivers not to park there','invite drivers to leave a car','explain how to repair a car','discourage doing something 是劝阻某行为。'),Q('discouraging',3,1,'Which news would be most discouraging to a job seeker?','another rejection after many applications','an invitation to a final interview','a reference praising her work','再次被拒会使求职者泄气。'),Q('discouraging',4,1,'“Discouraging people from wasting water” means?','trying to persuade them not to waste water','teaching them to waste more','recording how much water they drink','discourage someone from doing 表示劝阻。')]);
P('discoverer','discoverer 由 discover + -er 构成；discover 经古法语 descovrir“揭开、显露”，现代名词指首先发现或使某事为人所知的人。',C('discoverer.s1','科学史','The discoverer of the cave mapped its entrance carefully and published the location so archaeologists could assess the site.','洞穴的发现者仔细绘制了入口地图并公布位置，以便考古学家评估遗址。','The discoverer of the cave mapped its entrance carefully / and published the location / so archaeologists could assess the site.','discoverer of + 对象；so 引导目的或结果从句。','首先找到并公布洞穴的人符合发现者义。'),M('The discoverer was the last person to learn that the cave existed, decades after it became famous.','The latecomer was the last person to learn that the cave existed, decades after it became famous.','数十年后才知道洞穴的人不是首先发现者。'),[Q('discoverer',1,1,'A discoverer of a previously unknown species is?','someone who first finds or identifies it','someone who names every existing species','someone who sells animal photographs','discoverer 指首先发现或使某物为人所知的人。'),Q('discoverer',2,1,'The discoverer of a lost manuscript would be the person who?','first located or brought it to public attention','wrote every copy of the book','bought the most expensive edition','首先找到手稿的人符合 discoverer。'),Q('discoverer',3,1,'The suffix -er in discoverer refers to?','a person who performs the act of discovering','a place where books are stored','an action that will happen later','-er 表示做 discover 这一行为的人。'),Q('discoverer',4,1,'Which person is not the discoverer of an ancient site?','a visitor who arrived after it was already documented','the first researcher to locate it','the person who brought it to scholarly attention','后来到访者并非最初发现者。')]);
P('discrete','discrete 经拉丁语 discretus“分开的”进入英语，与 discernere“区分”相关；可表示彼此分离，也可指数学中取离散值的。',C('discrete.s2','数学与数据','The model reports age in discrete years, so a person is recorded as 20 or 21 rather than as every possible fraction between them.','模型以离散的整岁记录年龄，因此记录为20岁或21岁，而非其间所有可能的小数值。','The model reports age in discrete years / so a person is recorded as 20 or 21 / rather than as every possible fraction between them.','discrete 修饰 years；so 引出结果，rather than 对比连续取值。','只取分离的整值而非连续区间，体现数学义 s2。'),M('A discrete scale records every possible decimal value with no gaps between readings.','A continuous scale records every possible decimal value with no gaps between readings.','无间隙地取任意小数值是 continuous，不是 discrete。'),[Q('discrete',1,1,'Two discrete categories are?','separate and distinct from each other','parts of one unbroken continuum','the same category with two spellings','discrete 指分开、彼此不同。'),Q('discrete',2,2,'A discrete variable in mathematics takes?','separate values rather than every value in a continuum','all fractional values without gaps','only negative values','离散变量只能取分开的值。'),Q('discrete',3,1,'Which is a discrete count?','the number of books on a shelf','the exact temperature changing smoothly','a person’s height measured to any fraction','书本数量只能逐个计数，是离散值。'),Q('discrete',4,1,'Discrete should not be confused with “secret”; discrete here means?','separate or individually distinct','quietly hidden','polite in public','此处 discrete 是分离、独立，不是 secret。')]);
P('discrimination','discrimination 由 discriminate + -ion 构成，来自拉丁语 discriminare“区分”；可指基于身份的不公平待遇，也可指辨别细微差异的能力。',C('discrimination.s1','就业平等','The hiring policy prohibits discrimination based on age and requires every applicant to be assessed by the same job-related criteria.','招聘政策禁止年龄歧视，并要求按相同的工作相关标准评估每位申请人。','The hiring policy prohibits discrimination based on age / and requires every applicant to be assessed / by the same job-related criteria.','discrimination based on + 特征；prohibit 后接名词或动名词。','因年龄区别对待求职者属于不公平待遇义 s1。'),M('The hiring rule discriminated against no one, although it rejected applicants solely because they were over sixty.','The hiring rule discriminated against older applicants because it rejected them solely for being over sixty.','仅因年龄拒绝求职者是年龄歧视；不能说完全没有歧视。'),[Q('discrimination',1,1,'Employment discrimination based on age means?','unfairly treating applicants differently because of age','testing everyone by the same job-related standard','choosing the candidate with more relevant experience','基于年龄的不公平差别待遇是歧视。'),Q('discrimination',2,2,'A chef’s discrimination between fresh and spoiled fish is?','the ability to notice meaningful differences','unfair treatment of fish by age','a refusal to taste anything','此处 discrimination 指辨别好坏的能力。'),Q('discrimination',3,1,'Which action is discrimination?','denying housing to someone because of their religion','requiring all tenants to sign the same safety form','repairing a flat before renting it','因宗教身份拒绝住房属歧视。'),Q('discrimination',4,1,'The word discrimination can have a neutral positive sense when it means?','careful discernment or judgment','automatic prejudice','an identical choice in every case','辨别力一义本身可为中性或褒义。')]);
P('disempower','disempower 由 dis-“剥夺”与 empower“赋权”构成；empower 的词源与 power 同族，现代指剥夺个人或群体权力、控制感。',C('disempower.s1','社区治理','When officials made every decision without consulting residents, the process disempowered the neighborhood and weakened local participation.','官员作决定时完全不征求居民意见，这一过程削弱了社区的自主权，也降低了当地参与度。','When officials made every decision without consulting residents / the process disempowered the neighborhood / and weakened local participation.','disempower 是及物动词；without consulting 表示未征询。','居民失去参与决定与控制的能力，符合“剥夺权力”义。'),M('The new voting rules disempowered residents by giving each of them a meaningful voice in local decisions.','The new voting rules empowered residents by giving each of them a meaningful voice in local decisions.','给予发言权增强而非削弱居民影响力。'),[Q('disempower',1,1,'To disempower a group is to?','reduce its power or control','give it greater authority','teach it a new language','disempower 是削弱或剥夺权力。'),Q('disempower',2,1,'Which policy could disempower local residents?','removing their role in decisions about their own district','letting them vote on the district budget','publishing clear ways to submit proposals','剥夺居民决策参与会削弱其自主权。'),Q('disempower',3,1,'The opposite of disempower is?','empower','disregard','disappear','empower 是赋权，与 disempower 相反。'),Q('disempower',4,1,'A person may feel disempowered when?','every choice affecting them is made without their input','they receive authority to make a decision','their suggestions are taken seriously','完全无法参与影响自身的决定会让人感到失权。')]);
P('disenchantment','disenchantment 由 dis- 与 enchantment 构成；enchant 源自古法语 enchanter、拉丁语 incantare“施咒”，引申为迷住；disenchantment 指魅力消退后的失望。',C('disenchantment.s1','政治态度','Public disenchantment with the mayor grew after the promised housing repairs were postponed for a third year.','市长承诺的住房维修第三年继续延期后，公众对他的失望日益加深。','Public disenchantment with the mayor grew / after the promised housing repairs were postponed / for a third year.','disenchantment with + 对象；after 引出失望加深的原因。','公众曾期待其兑现承诺，如今失去信任与好感，符合 s1。'),M('Her disenchantment with the project grew because it exceeded every expectation and delighted the whole team.','Her enthusiasm for the project grew because it exceeded every expectation and delighted the whole team.','项目超出预期、令团队满意会带来 enthusiasm，不是失望。'),[Q('disenchantment',1,1,'Disenchantment with a leader is?','loss of faith or admiration','a stronger belief in the leader','a formal election result','disenchantment 指魅力消退后不再相信或欣赏。'),Q('disenchantment',2,1,'What might cause disenchantment with a service?','repeated promises that are never kept','a problem fixed promptly','a clear explanation of a delay','屡次食言容易使人失望、幻灭。'),Q('disenchantment',3,1,'Complete the common pattern: disenchantment ___ politics.','with','for to','at by','常见搭配是 disenchantment with。'),Q('disenchantment',4,1,'Someone who once admired a celebrity but now sees the flaws may feel?','disenchantment','enchantment','indifference to spelling only','原先的好感破灭后会感到 disenchantment。')]);
P('disengage','disengage 由 dis-“分离”与 engage“使连接、投入”构成；engage 源自古法语 engagier，disengage 可指解除机械连接，也可指退出参与。',C('disengage.s2','冲突降温','The mediator asked both neighbors to disengage from the argument for a few minutes and return when they could discuss the fence calmly.','调解员请两位邻居暂时退出争吵，等能平静讨论围栏时再回来。','The mediator asked both neighbors to disengage from the argument / for a few minutes / and return when they could discuss the fence calmly.','disengage from + 活动/冲突；ask sb to do sth。','暂时退出争论而非继续卷入，符合退出参与义 s2。'),M('The mediator told them to disengage from the quarrel, so they shouted at each other for another hour.','The mediator told them to remain engaged in the quarrel, so they shouted at each other for another hour.','继续争吵是仍参与冲突，不是退出冲突；应改为 remain engaged。'),[Q('disengage',1,2,'To disengage from a debate is to?','withdraw from taking part','introduce a new speaker','agree with every claim','退出辩论即停止参与。'),Q('disengage',2,1,'A mechanic disengages a clutch when she?','separates the engine’s drive from the wheels','paints the car’s door','increases tyre pressure','机械义是解除部件间的连接。'),Q('disengage',3,2,'A soldier ordered to disengage should?','pull back from combat','advance into the fight','ignore the order and fire','战术上 disengage 是脱离战斗。'),Q('disengage',4,1,'Which pattern is natural?','disengage from a heated exchange','disengage into the argument','disengage the debate from to','常用表达是 disengage from an exchange。')]);
P('disgraced','disgraced 是 disgrace 的过去分词形容词；disgrace 由 dis- 加 grace 构成，grace 源自拉丁语 gratia“恩惠、尊重”，此处指因丑闻失去名誉。',C('disgraced.s1','公共诚信','The disgraced treasurer resigned after an inquiry showed that he had used charity funds to pay personal debts.','调查显示财务主管挪用慈善资金偿还个人债务后，这位名誉扫地的主管辞职了。','The disgraced treasurer resigned / after an inquiry showed / that he had used charity funds to pay personal debts.','disgraced 修饰 treasurer；过去完成时 had used 表示调查前的行为。','侵吞善款造成公开失信，符合因丑行而失去尊重的义项。'),M('The disgraced official was admired more than ever because the audit cleared him of every accusation.','The cleared official was admired more than ever because the audit cleared him of every accusation.','审计洗清指控会恢复而非失去名誉；disgraced 与该事实不合。'),[Q('disgraced',1,1,'A disgraced official has?','lost public respect after shameful conduct','won universal admiration','just begun a new job','disgraced 指因丑闻或过错失去尊重。'),Q('disgraced',2,1,'Which event could leave a champion disgraced?','evidence that she cheated in the final','a fair loss to a stronger opponent','a record-breaking performance','作弊证据会严重损害名誉。'),Q('disgraced',3,1,'A disgraced leader may resign because?','public confidence has collapsed','the public has never heard of the event','the leader has received a medal','丑闻使公众信任丧失。'),Q('disgraced',4,1,'The closest opposite of a disgraced person is someone?','respected for honorable conduct','exposed for fraud','condemned by the public','因诚实行为受尊敬与失去名誉相反。')]);
P('disgraceful','disgraceful 由 disgrace 加 -ful 构成，指令人蒙羞、应受谴责的；disgrace 源于拉丁语 gratia“恩惠、尊重”。',C('disgraceful.s1','公共服务','Leaving the flooded shelter without drinking water for the elderly residents was a disgraceful failure of basic care.','让避难所里的老人缺水离开，是对基本照护职责的可耻失职。','Leaving the flooded shelter without drinking water for the elderly residents / was a disgraceful failure / of basic care.','disgraceful 修饰 failure；动名词短语作主语。','未提供基本照护、使弱势者受损，确实应受谴责。'),M('The committee called the team’s honest apology disgraceful, although it repaired the harm and accepted responsibility.','The committee called the team’s honest apology commendable, because it repaired the harm and accepted responsibility.','承担责任并弥补伤害值得肯定，并非可耻行为。'),[Q('disgraceful',1,1,'Disgraceful behaviour is?','shocking and deserving shame','ordinary and harmless','carefully praised by everyone','disgraceful 指令人蒙羞、应谴责的。'),Q('disgraceful',2,1,'Which act would most likely be called disgraceful?','stealing donations intended for disaster victims','returning lost money to its owner','admitting a harmless mistake','侵吞灾民捐款极其可耻。'),Q('disgraceful',3,1,'A disgraceful service failure makes customers feel?','the conduct deserves strong criticism','the company deserves a medal','nothing went wrong','该词表达强烈负面评价。'),Q('disgraceful',4,1,'The suffix -ful in disgraceful contributes the sense?','full of or characterized by disgrace','without any connection to shame','belonging to a group of people','-ful 构成“充满/具有某性质”的形容词。')]);
P('disgusted','disgusted 是 disgust 的过去分词形容词；disgust 经古法语源自拉丁语 gustus“味道”，原指坏味引发的反感，现也指道德厌恶。',C('disgusted.s1','食品安全','The inspector was disgusted to find insects in the restaurant’s uncovered flour bin and ordered the kitchen closed for cleaning.','检查员发现餐厅未加盖的面粉桶里有虫，感到极其厌恶，并下令关闭厨房清洁。','The inspector was disgusted to find insects in the restaurant’s uncovered flour bin / and ordered the kitchen closed for cleaning.','be disgusted to do 表示做某事时感到厌恶；find 后接宾语加地点短语。','腐败、污染食品引起强烈反感，符合 disgusted 的义项。'),M('She was disgusted by the spotless kitchen and said its perfect hygiene made her feel sick.','She was reassured by the spotless kitchen and said its perfect hygiene made her feel safe.','洁净厨房令人安心而非厌恶；disgusted 与称赞卫生相矛盾。'),[Q('disgusted',1,1,'A person who is disgusted feels?','strongly repelled or sickened','deeply amused','mildly curious','disgusted 指厌恶、反感。'),Q('disgusted',2,1,'Which discovery might leave a diner disgusted?','mold growing on the meal','a clean table near a window','a menu with clear prices','餐食发霉会让人厌恶。'),Q('disgusted',3,1,'Choose the natural construction.','disgusted by the rude remark','disgusted at to the rude remark','disgusted with doing rude remark it','be disgusted by + 引发厌恶的事物很自然。'),Q('disgusted',4,1,'If voters are disgusted by corruption, they are?','strongly repelled by it','delighted with it','unable to recognize it','腐败会引起强烈道德厌恶。')]);
P('dishabituate','dishabituate 由 dis- 与 habituate“使习惯”构成，habituate 源自拉丁语 habitus“状态、习惯”；心理学中指打破习惯化反应。',C('dishabituate.s1','行为实验','Researchers changed the tone after repeated identical beeps to dishabituate the infants and test whether they noticed the new sound.','研究人员在反复播放相同蜂鸣后改变音调，使婴儿脱离习惯化状态，以测试他们是否察觉新声音。','Researchers changed the tone after repeated identical beeps / to dishabituate the infants / and test whether they noticed the new sound.','dishabituate 是及物动词；to 引出实验目的。','改变刺激以恢复注意反应，符合打破习惯化义。'),M('The researcher repeated the same sound until the participant stopped noticing it, then called this dishabituating the response.','The researcher changed the sound so the participant noticed it again, thereby dishabituating the response.','反复相同刺激使反应习惯化；改变刺激、恢复注意才是 dishabituation。'),[Q('dishabituate',1,1,'To dishabituate a subject is to?','break a learned decline in response to a repeated stimulus','teach the subject to ignore every new stimulus','repeat an identical stimulus forever','dishabituate 是打破对重复刺激的习惯化。'),Q('dishabituate',2,1,'A researcher changes a repeated tone so a baby notices it again. The change may?','dishabituate the baby','habituate the baby further to the old tone','remove the baby from the experiment by definition','新刺激可能打破先前的习惯化反应。'),Q('dishabituate',3,1,'The prefix dis- in dishabituate here indicates?','reversal or disruption of habituation','a person who studies habits','a future tense marker','dis- 表示逆转/打破习惯化状态。'),Q('dishabituate',4,1,'Which observation best supports dishabituation?','attention returns when a familiar pattern changes','attention steadily fades as the same pattern repeats','the participant sleeps before the trial starts','刺激变化后注意力恢复，显示去习惯化。')]);
P('disharmony','disharmony 由 dis- 与 harmony 构成；harmony 经法语来自希腊语 harmonia“连接、协调”，disharmony 指人际不和或声音、部分之间不协调。',C('disharmony.s1','团队合作','There was disharmony between the design and engineering teams because each group kept changing the other’s specifications without discussion.','设计组和工程组之间出现不和，因为双方都不经讨论就改动对方的规格。','There was disharmony between the design and engineering teams / because each group kept changing the other’s specifications / without discussion.','disharmony between A and B；because 引出冲突原因。','双方缺乏协调、产生摩擦，体现人际不和。'),M('The choir displayed disharmony because every singer followed the conductor and the chords blended perfectly.','The choir displayed harmony because every singer followed the conductor and the chords blended perfectly.','歌手配合且和弦融合说明和谐，不是 disharmony。'),[Q('disharmony',1,1,'Disharmony among coworkers is?','lack of agreement or cooperation','perfectly smooth teamwork','a musical instrument','disharmony 指不和、不协调。'),Q('disharmony',2,1,'A chord sounds in disharmony when?','its notes clash rather than blend','all its notes fit together','the audience cannot see the stage','不协调的音高会彼此冲突。'),Q('disharmony',3,1,'Which action could reduce disharmony in a team?','agreeing on shared responsibilities','changing others’ plans without notice','withholding all project information','事先商定职责有助于协调、减少冲突。'),Q('disharmony',4,1,'The closest opposite of disharmony is?','harmony','friction','discord','harmony 是和谐，与 disharmony 相对。')]);
P('dishonesty','dishonesty 由 dis- 与 honesty 构成；honesty 来自 honest，最终源于拉丁语 honestus“体面、受尊敬”，dishonesty 指说谎、欺骗或偷窃的品质/行为。',C('dishonesty.s1','学术诚信','The university treated the copied paragraph as academic dishonesty and asked the student to provide the sources used for the assignment.','大学将抄来的段落视为学术不诚信，并要求学生提供作业所用资料来源。','The university treated the copied paragraph as academic dishonesty / and asked the student / to provide the sources used for the assignment.','dishonesty 常作不可数名词；treat A as B 表示把 A 视为 B。','未经标注地复制文字属于欺骗性的学术行为。'),M('The audit found no dishonesty, although the cashier secretly removed money from the register.','The audit found dishonesty, because the cashier secretly removed money from the register.','偷偷拿走收银款是明确的不诚实行为，不能说没有 dishonesty。'),[Q('dishonesty',1,1,'Dishonesty includes?','lying or cheating for personal advantage','admitting an error openly','returning a borrowed item','dishonesty 包括说谎和欺骗。'),Q('dishonesty',2,1,'A report finds dishonesty in an expense claim when an employee?','submits a receipt for a purchase never made','lists a real business meal accurately','asks whether a cost is allowed','虚报未发生的支出属于欺骗。'),Q('dishonesty',3,1,'The closest opposite of dishonesty is?','honesty','deception','fraud','honesty 表示诚实。'),Q('dishonesty',4,1,'Academic dishonesty could involve?','presenting another person’s work as one’s own','citing a source accurately','asking a teacher for clarification','把他人作品冒充自己的构成学术不诚信。')]);
P('disillusion','disillusion 源于法语 désillusion，由 dis- 与 illusion“幻觉、错觉”组成，可作动词“使认清真相”，也可作名词“幻灭状态”。',C('disillusion.s1','公众信任','The investigation disillusioned many donors by showing that the charity had spent most of its public appeal on executive travel.','调查显示慈善机构把公开募款的大部分用于高管差旅，使许多捐赠者的幻想破灭。','The investigation disillusioned many donors / by showing that the charity had spent most of its public appeal on executive travel.','disillusion 是及物动词；by + 动名词说明使人醒悟的方式。','真相打破了捐赠者对机构的理想化看法，符合动词义 s1。'),M('The transparent audit disillusioned donors by proving that every contribution had reached the intended families.','The transparent audit reassured donors by proving that every contribution had reached the intended families.','证明资金妥善使用会让捐赠者安心，而不是幻灭。'),[Q('disillusion',1,1,'To disillusion someone is to?','make that person see that a belief was mistaken','strengthen a pleasant false belief','prevent that person from learning anything','disillusion 指使人认清原有信念不切实际。'),Q('disillusion',2,2,'After years of disappointment, her disillusion with the party deepened. Here disillusion is?','a state of lost belief or idealism','the act of creating a new illusion','a political election','名词义指失去原有理想或信念的状态。'),Q('disillusion',3,1,'An honest report may disillusion fans if it?','reveals serious faults hidden behind a polished image','confirms every rumor is false','introduces the team mascot','揭示隐藏缺陷可能使粉丝幻想破灭。'),Q('disillusion',4,1,'Which word is closest to the verb disillusion?','enlighten by exposing a false hope','deceive with a new promise','decorate for a celebration','揭开不切实际的希望使人清醒。')]);
P('disillusioned','disillusioned 是 disillusion 的过去分词形容词，描述一个人因发现现实不符理想而不再信任或崇拜。',C('disillusioned.s1','职业选择','After three unpaid internships and repeated broken promises, Leo became disillusioned with the media company and sought work elsewhere.','经历三次无薪实习和一再食言后，利奥对这家媒体公司失去了信心，转而另找工作。','After three unpaid internships and repeated broken promises / Leo became disillusioned with the media company / and sought work elsewhere.','be disillusioned with + 对象；become 描述状态变化。','现实反复违背期望，使其不再信任公司。'),M('The disillusioned volunteers trusted the organization more than ever after it concealed its finances again.','The reassured volunteers trusted the organization more than ever after it disclosed its finances.','公开财务使志愿者安心；隐瞒财务则不符合信任增加这一结果。'),[Q('disillusioned',1,1,'A disillusioned supporter has?','lost faith after seeing disappointing facts','become more idealistic after success','never held an opinion','disillusioned 指因认清现实而幻灭、失去信心。'),Q('disillusioned',2,1,'Which event may leave a voter disillusioned with a candidate?','the candidate repeatedly breaks key promises','the candidate explains a policy clearly','the candidate admits a small error','一再违背承诺会使支持者失望。'),Q('disillusioned',3,1,'A disillusioned employee is likely to?','no longer believe the company’s inspiring claims','trust every announcement automatically','be unable to read the company name','幻灭后不再轻信公司的宣传。'),Q('disillusioned',4,1,'Complete the natural phrase: disillusioned ___ the process.','with','by to','on at','常用结构是 disillusioned with。')]);
P('disillusionment','disillusionment 由 disillusion 加名词后缀 -ment 构成，指原有理想或信念破灭后产生的失望。',C('disillusionment.s1','政治参与','A wave of disillusionment followed the inquiry, as residents learned that the promised repairs had never been budgeted.','调查之后，居民得知承诺的维修从未列入预算，一阵幻灭和失望情绪随之而来。','A wave of disillusionment followed the inquiry / as residents learned / that the promised repairs had never been budgeted.','a wave of + 不可数抽象名词；as 引原因背景。','原先相信承诺会落实，如今发现并无预算，导致信念破灭。'),M('The inquiry caused disillusionment because it confirmed every promise had been fulfilled exactly as advertised.','The inquiry caused reassurance because it confirmed every promise had been fulfilled exactly as advertised.','证实承诺兑现会让人安心，而非产生幻灭。'),[Q('disillusionment',1,1,'Disillusionment is?','disappointment after a false hope is exposed','a stronger feeling of wonder','a plan for future travel','disillusionment 是幻想破灭后的失望。'),Q('disillusionment',2,1,'What could cause disillusionment with a public project?','discovering that its celebrated benefits were never delivered','seeing the project meet its goals','receiving a clear schedule','承诺的好处并未兑现会使公众幻灭。'),Q('disillusionment',3,1,'The noun disillusionment is related to which adjective?','disillusioned','disillusioningness','disillusionedly only','disillusionment 表示产生 disillusioned 状态的失望。'),Q('disillusionment',4,1,'A novel may portray a character’s disillusionment when the character?','abandons an ideal after learning the truth','discovers a new hobby and enjoys it','forgets the title of a book','认清真相后放弃理想是幻灭过程。')]);
P('disinfect','disinfect 由 dis-“去除”与 infect“感染”组成；infect 源自拉丁语 inficere“染上、污染”，disinfect 指杀灭或去除物体表面的病菌。',C('disinfect.s1','家庭清洁','After cutting raw chicken, Sam disinfected the counter with a food-safe cleaner before placing vegetables on it.','处理生鸡肉后，萨姆用适用于食品接触面的清洁剂给台面消毒，才把蔬菜放上去。','After cutting raw chicken / Sam disinfected the counter with a food-safe cleaner / before placing vegetables on it.','disinfect 是及物动词；disinfect A with B 表示用 B 给 A 消毒。','清除生肉可能留下的病菌，符合消毒义。'),M('She disinfected the counter by wiping it with a dry cloth that did not remove or kill germs.','She dusted the counter with a dry cloth, then disinfected it with an approved cleaner.','单纯干布擦拭并未杀灭病菌，不足以称为 disinfect。'),[Q('disinfect',1,1,'To disinfect a surface is to?','destroy germs on it','make it smell stronger','paint it a different color','disinfect 指杀灭表面的病菌。'),Q('disinfect',2,1,'A nurse should disinfect an instrument when?','after use and before it is used again','while it is being stored permanently','only after it rusts','再次使用前要按规程清洁消毒器械。'),Q('disinfect',3,1,'Which item is most likely used to disinfect a countertop?','an approved germ-killing solution','a dry decorative cloth only','a measuring tape','消毒液可杀灭台面上的病菌。'),Q('disinfect',4,1,'The verb disinfect is the opposite of?','contaminate with germs','sanitize','sterilize','contaminate with germs 与消毒杀菌相反。')]);
P('disinhibition','disinhibition 由 dis- 与 inhibition 构成；inhibition 源自拉丁语 inhibere“抑制、阻止”，心理或神经科学中指行为抑制机制减弱。',C('disinhibition.s1','神经心理','The clinician noted disinhibition after the brain injury because the patient began making impulsive remarks that he had previously controlled.','脑损伤后，患者开始说出从前会克制的冲动言论，临床人员因此记录了行为抑制减弱。','The clinician noted disinhibition after the brain injury / because the patient began making impulsive remarks / that he had previously controlled.','disinhibition 作不可数名词；because 引出判断依据。','原本受控的言行变得冲动，体现抑制减少。'),M('The patient’s new disinhibition meant he became more restrained and carefully filtered every remark.','The patient’s new inhibition meant he became more restrained and carefully filtered every remark.','克制增强是 inhibition；disinhibition 表示行为约束减弱。'),[Q('disinhibition',1,1,'Disinhibition is a reduction in?','the restraints that normally hold behaviour back','the ability to see colors','the length of a sentence','disinhibition 是行为抑制减弱。'),Q('disinhibition',2,1,'A person showing social disinhibition may?','make unusually impulsive remarks','carefully avoid every spontaneous comment','become unable to move a muscle','社交抑制减弱可能让人冲动发言。'),Q('disinhibition',3,1,'In neuroscience, disinhibition can follow?','reduced control by inhibitory brain systems','a stronger ability to suppress all impulses','a change in shoe size','神经抑制系统控制减弱会导致 disinhibition。'),Q('disinhibition',4,1,'The prefix dis- in disinhibition signals?','removal or weakening of inhibition','a state of perfect restraint','the plural of inhibition','dis- 在此表示抑制被解除或削弱。')]);
P('disintegration','disintegration 由 dis- 与 integration 构成；integrate 源自拉丁语 integer“完整的”，disintegration 可指社会/关系瓦解，也可指物质碎裂。',C('disintegration.s2','材料科学','The porous tablet’s disintegration began as soon as it touched water, breaking into small particles that could dissolve.','多孔药片一碰到水便开始崩解，碎成能够溶解的小颗粒。','The porous tablet’s disintegration began as soon as it touched water / breaking into small particles / that could dissolve.','disintegration 作不可数名词；begin as soon as 表示一……就……。','固体分裂成小颗粒，符合物质破碎义 s2。'),M('The tablet showed disintegration because it stayed whole and solid after an hour in water.','The tablet showed no disintegration because it stayed whole and solid after an hour in water.','浸水一小时仍完整说明没有崩解。'),[Q('disintegration',1,2,'A tablet’s disintegration in liquid is?','its breaking apart into smaller pieces','its becoming a single larger tablet','its label changing color only','物质义指崩解为小块。'),Q('disintegration',2,1,'The disintegration of a coalition means?','the group is breaking up','the group is gaining new members','the group is meeting as usual','组织义指联盟瓦解。'),Q('disintegration',3,2,'Which observation shows physical disintegration?','a dry block crumbles into fragments','a metal bar remains unchanged','a sealed box is moved intact','碎裂成片段说明物质崩解。'),Q('disintegration',4,1,'The closest opposite of disintegration is?','integration','fragmentation','collapse','integration 表示整合、结合，与瓦解相反。')]);
P('disinterest','disinterest 由 dis- 与 interest 构成，可作名词表示缺乏兴趣/关注，也可作动词表示使人失去兴趣；名词也曾有“公正无私”义，但现较少见。',C('disinterest.s2','观众参与','The lecturer’s long list of unexplained abbreviations seemed to disinterest the audience, and several listeners stopped taking notes.','讲师列出一长串未解释的缩写，似乎让听众失去兴趣，几位听众不再记笔记。','The lecturer’s long list of unexplained abbreviations / seemed to disinterest the audience / and several listeners stopped taking notes.','disinterest 作及物动词；seem to 后接动词原形。','晦涩表达使听众不再投入，符合动词义 s2。'),M('The dull presentation disinterested the audience, so every listener leaned forward with keen attention.','The lively presentation interested the audience, so every listener leaned forward with keen attention.','全神贯注说明听众有兴趣；dull/disinterested 与结果冲突。'),[Q('disinterest',1,1,'A reader’s disinterest in a topic means?','a lack of curiosity or concern','a strong desire to learn more','a detailed understanding of it','disinterest 名词义表示缺乏兴趣。'),Q('disinterest',2,2,'To disinterest an audience is to?','cause it to lose interest','make it more curious','ask it to vote','动词 disinterest 指使人失去兴趣。'),Q('disinterest',3,1,'A speaker may disinterest listeners by?','reading dense slides without explaining the terms','telling a clear story with useful examples','answering the audience’s questions','难懂且不解释的展示会使听众失去兴趣。'),Q('disinterest',4,1,'Which sentence uses disinterest as a verb?','The repetitive lecture disinterested the class.','Her disinterest in politics was obvious.','They discussed the public interest.','第一句中 disinterested 是使人失去兴趣的动词过去式。')]);
P('disinterested','disinterested 由 dis- 与 interested 构成；现代主要指不偏袒、无私利牵涉，另可指缺乏兴趣；传统用法不宜把后者一概判错。',C('disinterested.s1','仲裁程序','Because neither bidder was related to the company, the board appointed both as disinterested observers of the contract review.','由于两名投标人都与公司没有关联，董事会任命他们为合同审查的无利益关系观察员。','Because neither bidder was related to the company / the board appointed both as disinterested observers / of the contract review.','disinterested observer 指无私利牵涉、较能保持公正的观察者。','与公司无关联、无利益冲突，符合公正无私义 s1。'),M('The disinterested judge owned shares in one bidder and stood to profit from its selection.','The interested judge owned shares in one bidder and stood to profit from its selection.','持有投标方股份构成利益冲突，不能称 disinterested（公正无私）。'),[Q('disinterested',1,1,'A disinterested arbitrator is?','free from personal stake or bias in the outcome','bored by every topic','financially invested in one side','仲裁语境中 disinterested 指无利益牵涉。'),Q('disinterested',2,2,'In “She was disinterested in the lecture,” the word means?','she lacked interest in it','she judged it impartially','she owned the lecture hall','此处根据搭配 in 表示缺乏兴趣。'),Q('disinterested',3,1,'Which person is best suited as a disinterested reviewer?','someone with no financial connection to the applicant','the applicant’s business partner','a person promised a bonus for approval','无经济关系者更可能公正评审。'),Q('disinterested',4,1,'Modern careful writing uses disinterested chiefly for?','impartial and without personal stake','always bored','highly enthusiastic','主要义是公正无私；缺乏兴趣也有用例。')]);
P('disjointed','disjointed 由 dis- 与 joint 构成；joint 与拉丁语 iungere“连接”同源，disjointed 描述缺少逻辑连接、不连贯的部分。',C('disjointed.s1','叙事写作','The witness gave a disjointed account, jumping from the station to the hospital without explaining how he travelled between them.','证人的叙述缺乏连贯性，从车站突然跳到医院，却没有说明中间如何移动。','The witness gave a disjointed account / jumping from the station to the hospital / without explaining how he travelled between them.','disjointed 修饰 account；现在分词短语补充说明叙述跳跃之处。','信息之间缺少衔接，符合不连贯义。'),M('Her disjointed explanation followed a clear timeline and linked each event with an explicit cause.','Her coherent explanation followed a clear timeline and linked each event with an explicit cause.','按时间顺序并有因果衔接的解释是连贯的。'),[Q('disjointed',1,1,'A disjointed story is?','poorly connected and hard to follow','organized in a clear sequence','a story with no characters','disjointed 指各部分缺少连接、难以理解。'),Q('disjointed',2,1,'A speech sounds disjointed when it?','jumps between unrelated points','develops one claim step by step','uses clear transitions','不断跳到无关观点体现不连贯。'),Q('disjointed',3,1,'Which revision would improve a disjointed report?','add transitions that explain how sections relate','shuffle the paragraphs randomly','remove the main topic sentence','补充逻辑过渡能改善衔接。'),Q('disjointed',4,1,'The closest opposite of disjointed is?','coherent','fragmented','disconnected','coherent 表示连贯。')]);
P('disjunction','disjunction 由 dis- 与 junction 构成；junction 源自拉丁语 iungere“连接”，disjunction 指两事物之间断裂、不相符，逻辑学中亦指“或”关系。',C('disjunction.s1','论证评估','There is a disjunction between the report’s claim that costs fell and its table showing a steady rise in every quarter.','报告声称成本下降，但表格显示每个季度都持续上涨，两者存在不一致。','There is a disjunction between the report’s claim that costs fell / and its table showing a steady rise / in every quarter.','disjunction between A and B；后者与前者不相符。','主张与数据彼此不吻合，体现断裂/不一致义。'),M('The report showed no disjunction between its claim and the data, which plainly contradicted that claim.','The report showed a disjunction between its claim and the data, which plainly contradicted that claim.','数据直接反驳主张，显然存在不一致。'),[Q('disjunction',1,1,'A disjunction between two accounts is?','a gap or mismatch between them','perfect agreement in every detail','a shared source citation','disjunction 可指两方不相符或脱节。'),Q('disjunction',2,1,'A logic statement “A or B” may express?','a disjunction','a synonym','a cause-and-effect chain','逻辑中的“或”常以 disjunction 表示。'),Q('disjunction',3,1,'Which example shows a disjunction?','a policy promises lower fees while the bill raises them','a forecast and measurements both show rain','two witnesses agree on the time','承诺降费却实际涨费，两者不吻合。'),Q('disjunction',4,1,'The noun disjunction is related to?','junction, a point of joining','judgment, a final ruling','jungle, a forest','junction 指连接处，disjunction 指断开/不一致。')]);
P('dislodge','dislodge 由 dis-“离开”与 lodge“安置、嵌入”构成；lodge 经古法语源自日耳曼语，动词指把卡住或固定的东西移开。',C('dislodge.s1','急救与清理','A firm cough helped dislodge the crumb stuck in his throat, and he could breathe normally again.','他用力咳嗽，咳出了卡在喉咙里的面包屑，随后又能正常呼吸。','A firm cough helped dislodge the crumb stuck in his throat / and he could breathe normally again.','help + 宾语 + 动词原形；dislodge A stuck in B。','咳嗽使嵌住的面包屑脱离原位，符合该词义。'),M('The vibration dislodged the loose stone by fixing it more firmly in the wall.','The vibration lodged the loose stone more firmly in the wall.','固定得更牢是 lodge；dislodge 表示将其移出原位。'),[Q('dislodge',1,1,'To dislodge a stuck object is to?','force it out of its position','attach it more securely','measure its length','dislodge 指把卡住的东西弄出来。'),Q('dislodge',2,1,'A gust may dislodge a roof tile by?','knocking it loose','painting it','making it heavier but fixed','强风可能把屋瓦掀松。'),Q('dislodge',3,1,'Which verb is closest to dislodge here: “The dentist dislodged the seed”?','removed','planted','polished','把卡住的籽取出就是 removed。'),Q('dislodge',4,1,'The opposite of dislodge in “dislodge a plug” is?','lodge it securely','pull it out','knock it loose','将塞子稳固嵌入与移出相反。')]);
P('disloyalty','disloyalty 由 dis- 与 loyalty 构成；loyal 来自古法语 loial、拉丁语 legalis“守法的”，现代指背叛承诺或不忠的行为/品质。',C('disloyalty.s1','合作关系','The captain viewed the leaked strategy as disloyalty to the team because it gave their opponents an avoidable advantage.','队长认为泄露战术是对团队的不忠，因为这让对手获得了本可避免的优势。','The captain viewed the leaked strategy as disloyalty to the team / because it gave their opponents / an avoidable advantage.','disloyalty to + 对象；view A as B 表示把 A 视为 B。','泄露队伍机密损害盟友利益，属于背信行为。'),M('Her disloyalty to the club consisted of keeping every promise and protecting all confidential plans.','Her loyalty to the club consisted of keeping every promise and protecting all confidential plans.','守信并保护机密体现忠诚，不能称 disloyalty。'),[Q('disloyalty',1,1,'Disloyalty to a group involves?','betraying its trust or commitments','supporting it faithfully','following an agreed rule','disloyalty 指背叛信任或承诺。'),Q('disloyalty',2,1,'Which act could be disloyalty to a friend?','sharing a private confidence to embarrass them','keeping a secret they entrusted to you','helping them during a difficult week','泄露朋友托付的秘密可能构成不忠。'),Q('disloyalty',3,1,'A common structure is “disloyalty ___ one’s country.”','to','for','by at','常见介词搭配为 disloyalty to。'),Q('disloyalty',4,1,'The opposite of disloyalty is?','loyalty','betrayal','abandonment','loyalty 表示忠诚。')]);
P('dismember','dismember 由 dis-“分开”与 member“肢体、部分”构成；member 经古法语源自拉丁语 membrum“肢体”，既可指肢解身体，也可比喻拆分组织或国家。',C('dismember.s2','政治史','The treaty would dismember the province, transferring its northern districts to one neighbor and its southern ports to another.','条约将肢解该省，把北部地区划给一个邻国，把南部港口划给另一个邻国。','The treaty would dismember the province / transferring its northern districts to one neighbor / and its southern ports to another.','dismember 是及物动词；transfer A to B 描述领土拆分。','一个政治实体被拆成若干部分，体现比喻义 s2。'),M('The treaty dismembered the province by preserving its borders and keeping every district under one administration.','The treaty preserved the province by keeping its borders and every district under one administration.','维持边界与统一管理是保存完整，不是拆分省份。'),[Q('dismember',1,1,'To dismember a political state is to?','break it into separate parts','unite it under one government','write a history of it','比喻义 dismember 指拆分政治实体。'),Q('dismember',2,1,'The literal meaning of dismember concerns?','cutting off the limbs of a body','joining bones together','examining a living plant’s leaves','字面义与肢体被切离有关。'),Q('dismember',3,1,'A plan to divide a company into independent units could?','dismember the company','disinfect the company','discompose its customers','把组织拆成部分可比喻为 dismember。'),Q('dismember',4,2,'Which event best illustrates the figurative sense?','a country is divided among several new states','a doctor studies one arm','a team adds a new member','国家被拆分最能体现政治义。')]);
P('dismemberment','dismemberment 由 dismember 加 -ment 构成；member 经拉丁语 membrum“肢体”，名词可指肢解，也可指一个整体被拆散。',C('dismemberment.s1','历史与法律','The inquiry described the dismemberment of the body in restrained clinical language, avoiding unnecessary detail in its public summary.','调查报告用克制的临床语言描述了尸体肢解情况，在公开摘要中避免不必要的细节。','The inquiry described the dismemberment of the body / in restrained clinical language / avoiding unnecessary detail in its public summary.','dismemberment 为不可数名词；describe A in language 表示用某种语言描述。','语境明确是身体被肢解，匹配 s1。'),M('The report used dismemberment to mean that the intact body had not been cut or divided in any way.','The report used preservation to mean that the intact body had not been cut or divided in any way.','未被切割或分开的状态不是 dismemberment。'),[Q('dismemberment',1,1,'The literal sense of dismemberment is?','the cutting apart of a body’s limbs','the joining of a body’s bones','the study of a person’s family','字面义指肢体被切离。'),Q('dismemberment',2,1,'The dismemberment of an empire describes?','its breakup into separate territories','its expansion under one ruler','its peaceful trade agreement','政治义是帝国被分裂为多个部分。'),Q('dismemberment',3,1,'The suffix -ment turns dismember into?','a noun for the act or result','a person who performs the action','an adverb of manner','-ment 构成行为或结果名词。'),Q('dismemberment',4,1,'Which phrase uses dismemberment figuratively?','the dismemberment of a once-unified federation','the repair of a fractured limb','a surgeon’s anatomy lesson','联邦拆分是比喻用法。')]);
P('dismissive','dismissive 由 dismiss 加 -ive 构成；dismiss 源自拉丁语 dimittere“送走、放弃”，dismissive 描述轻蔑地把人或观点视为不值得考虑。',C('dismissive.s1','工作沟通','When Priya raised a safety concern, her manager gave a dismissive shrug and changed the subject without answering her question.','普丽娅提出安全顾虑时，经理轻蔑地耸耸肩，没有回答就转移了话题。','When Priya raised a safety concern / her manager gave a dismissive shrug / and changed the subject without answering her question.','dismissive 修饰 shrug；without answering 表示未回应。','经理不认真对待她的问题，显得轻慢、不屑。'),M('The chair was dismissive of the concern because she invited the speaker to explain it fully and ordered an investigation.','The chair took the concern seriously because she invited the speaker to explain it fully and ordered an investigation.','邀请详述并启动调查表示认真对待，并非轻蔑打发。'),[Q('dismissive',1,1,'A dismissive reply treats a concern as?','unworthy of serious attention','important enough to investigate','a request for more details','dismissive 指不屑一顾。'),Q('dismissive',2,1,'Which response sounds dismissive?','“That is nonsense,” followed by turning away','“Please explain the evidence so we can assess it.”','“I will record your concern and follow up.”','嘲称胡说并转身离开，是轻视对方。'),Q('dismissive',3,1,'A dismissive tone toward a colleague is likely to seem?','contemptuous or belittling','patient and receptive','neutral because it gives full consideration','dismissive 的语气轻蔑、贬低。'),Q('dismissive',4,1,'The closest opposite of dismissive is?','considerate','scornful','offhand','认真体谅的态度与轻蔑相反。')]);
P('disorderly','disorderly 由 disorder 加 -ly 构成，disorder 含 dis- 与 order“秩序”；可指杂乱无序，也可指在公共场合喧闹滋事。',C('disorderly.s2','公共秩序','Police removed two disorderly spectators after they threw bottles and tried to rush onto the playing field.','两名观众扔瓶子并试图冲进球场，警方随后将这两名扰乱秩序的人带离。','Police removed two disorderly spectators / after they threw bottles / and tried to rush onto the playing field.','disorderly 修饰 spectators；after 引出被带离的原因。','扔瓶并冲闯场地属于公开的扰乱秩序行为，符合 s2。'),M('The orderly crowd was called disorderly even though everyone remained seated and followed the ushers’ instructions.','The orderly crowd was praised because everyone remained seated and followed the ushers’ instructions.','安静就座并遵从指示体现守秩序，不应称 disorderly。'),[Q('disorderly',1,1,'Disorderly conduct in public involves?','disruptive or unruly behaviour','quietly waiting in a line','following safety instructions','该词的公共行为义指滋事或扰乱秩序。'),Q('disorderly',2,1,'A disorderly desk is?','messy and not arranged neatly','cleanly sorted by topic','locked and unused','普通形容词义也可表示杂乱无序。'),Q('disorderly',3,2,'Which scene is disorderly in the public-behaviour sense?','spectators shove one another and throw objects','visitors sit quietly through a talk','children line up before entering','推搡扔东西是滋事行为。'),Q('disorderly',4,1,'A disorderly room most nearly needs?','tidying and organization','more scattered papers','a louder argument','房间杂乱，需要收拾整理。')]);
P('disorganised','disorganised 是 disorganise 的过去分词形容词，英式拼写用 -ise；disorganise 由 dis- 与 organize 构成，表示安排混乱或缺乏条理。',C('disorganised.s1','日程管理','Because the coordinator was disorganised, two speakers were booked for the same room at the same time and neither received the updated schedule.','由于协调员缺乏条理，两位发言者被安排在同一时间使用同一房间，且都没收到更新后的日程。','Because the coordinator was disorganised / two speakers were booked for the same room at the same time / and neither received the updated schedule.','disorganised 描述人的工作状态；because 引出结果原因。','重复预订并漏发通知体现缺乏计划组织。'),M('The disorganised coordinator checked every booking twice, sent updates promptly, and left no task unassigned.','The well-organised coordinator checked every booking twice, sent updates promptly, and left no task unassigned.','核对周全、及时通知显示有条理，不是 disorganised。'),[Q('disorganised',1,1,'A disorganised planner is likely to?','lose track of appointments','keep a clear, updated schedule','finish every task in order','disorganised 指缺乏条理。'),Q('disorganised',2,1,'Which spelling is standard in British English?','disorganised','disorganisated','disorganizeed','英式过去分词常拼作 disorganised。'),Q('disorganised',3,1,'A disorganised folder system has?','files stored without a useful order','documents grouped by clear labels','one complete index','无实用分类的文件夹系统混乱无序。'),Q('disorganised',4,1,'The closest opposite is?','well-organised','untidy','chaotic','well-organised 与 disorganised 相反。')]);
P('disorganization','disorganization 由 dis-、organization 构成，美式拼写以 -zation 结尾；指缺乏良好安排，organization 经 organize 加 -ation 构成。',C('disorganization.s1','行政流程','The disorganization in the clinic’s filing system delayed referrals because staff could not find current patient records.','诊所档案系统混乱，工作人员找不到最新病历，转诊因此延误。','The disorganization in the clinic’s filing system delayed referrals / because staff could not find current patient records.','disorganization 作不可数名词；because 解释延误原因。','记录无序并导致工作无法顺利运行，符合定义。'),M('The office’s disorganization made every file easy to locate because documents were alphabetized and indexed.','The office’s organization made every file easy to locate because documents were alphabetized and indexed.','字母排序且有索引体现 organization，而非 disorganization。'),[Q('disorganization',1,1,'Disorganization in an office is?','a lack of orderly arrangement','a carefully maintained filing system','a schedule with clear responsibilities','disorganization 指组织安排混乱。'),Q('disorganization',2,1,'What is evidence of disorganization in a clinic?','staff repeatedly lose essential records','all files have current labels','appointments follow a clear schedule','重要病历反复遗失说明系统缺乏组织。'),Q('disorganization',3,1,'The American spelling ends with?','-ization','-isation only','-izzation','美式常用拼写为 disorganization。'),Q('disorganization',4,1,'A likely result of disorganization is?','delays caused by misplaced information','faster work through clear procedures','perfect knowledge of every file location','资料找不到会造成延误。')]);
P('disorganize','disorganize 由 dis- 与 organize 构成，organize 经古法语组织词源关联希腊语 organon“工具”；动词指使系统或群体陷入混乱。',C('disorganize.s1','物流运作','A sudden change to the loading plan could disorganize the warehouse, so the supervisor posted the new sequence before the trucks arrived.','突然更改装货计划可能打乱仓库运作，因此主管在卡车抵达前公布了新顺序。','A sudden change to the loading plan could disorganize the warehouse / so the supervisor posted the new sequence / before the trucks arrived.','disorganize 是及物动词；could 后接原形，so 引出预防措施。','改变计划会打乱仓库原有协调秩序，符合动词义。'),M('The surprise cancellation disorganized the schedule even though every appointment remained exactly as planned.','The surprise cancellation disrupted the schedule by forcing several appointments to be rearranged.','安排全部照旧与取消造成混乱的说法相矛盾。'),[Q('disorganize',1,1,'To disorganize a team is to?','make its work less orderly','give it a clear plan','increase cooperation','disorganize 指使组织变得无序。'),Q('disorganize',2,1,'A last-minute room change may disorganize a conference if it?','forces several sessions and staff assignments to be rearranged','is announced early with a map','leaves the timetable unchanged','临时改房可能打乱会议安排。'),Q('disorganize',3,1,'Which verb is closest to disorganize here?','disrupt','coordinate','sort','打乱秩序相当于 disrupting。'),Q('disorganize',4,1,'A manager avoids disorganizing a shift by?','communicating changes before staff arrive','changing assignments without telling anyone','removing the duty roster','提前传达变化能避免扰乱工作。')]);
P('disorganized','disorganized 是 disorganize 的过去分词形容词，美式拼写用 -ize；描述计划或物品未整理，也可描述做事没有条理。',C('disorganized.s1','项目协作','The disorganized project folder contained duplicate drafts, unlabeled charts, and no copy of the final approved report.','杂乱的项目文件夹里有重复草稿、未标注图表，也没有最终批准版报告。','The disorganized project folder contained duplicate drafts / unlabeled charts / and no copy of the final approved report.','disorganized 作定语；并列名词短语列举杂乱的证据。','文件重复且缺乏标签、终稿，显示没有妥善整理。'),M('Her disorganized notes were easy to search because every page had a date, title, and index number.','Her well-organized notes were easy to search because every page had a date, title, and index number.','每页有日期、标题和索引说明笔记有条理。'),[Q('disorganized',1,1,'A disorganized desk is?','untidy and difficult to work from','neatly sorted into labeled sections','empty by design','disorganized 可描述杂乱无序。'),Q('disorganized',2,1,'A disorganized person may often?','forget where tasks or materials were put','record each appointment in a clear calendar','prepare materials in advance','缺乏条理的人容易忘记任务或物品位置。'),Q('disorganized',3,1,'Which spelling is standard in American English?','disorganized','disorganised only','disorganizeing','美式拼法为 disorganized。'),Q('disorganized',4,1,'Which change would make a disorganized archive more usable?','label folders and remove duplicate files','mix files randomly','delete the index','给文件夹标注并清除重复项可改善组织。')]);
P('disorient','disorient 由 dis-“使失去”与 orient“确定方向”构成；orient 经法语源自拉丁语 oriens“东方、日出方向”，动词指使人迷失方位或不知所措。',C('disorient.s1','旅行与空间感','The identical corridors disoriented visitors, so the museum added color-coded signs at each junction.','走廊外观相同，让参观者辨不清方向，因此博物馆在每个岔口增设了颜色标识。','The identical corridors disoriented visitors / so the museum added color-coded signs / at each junction.','disorient 是及物动词；so 表示针对迷路问题采取的措施。','相似走廊使人无法判断所在位置，符合迷失方向义。'),M('The clear map disoriented hikers by showing their exact location and the marked trail ahead.','The clear map oriented hikers by showing their exact location and the marked trail ahead.','清晰地图帮助确认位置、方向，是 orient 而非 disorient。'),[Q('disorient',1,1,'To disorient a traveler is to?','make it hard for them to know where they are','show them the route clearly','tell them the local time','disorient 指使人迷失方向。'),Q('disorient',2,1,'A sudden time-zone change may disorient someone by?','making local time and routine feel confusing','providing a familiar schedule','improving a map’s accuracy','时差变化可能让人对时间和日常节奏混乱。'),Q('disorient',3,1,'Which setting would most likely disorient a visitor?','a maze of identical unmarked corridors','a hall with clear signs at every turn','a small room with one labeled door','无标识且相同的走廊容易让人迷路。'),Q('disorient',4,1,'The opposite of disorient is?','orient','confuse','mislead','orient 表示确定方向，与 disorient 相反。')]);
P('disorientate','disorientate 由 dis- 与 orientate 构成，是 disorient 的英语扩展变体；orientate 与 orient 同源，常用义为使人迷失方向或困惑。',C('disorientate.s1','建筑导览','The maze-like renovation could disorientate first-time visitors, so the library kept the old entrance and installed signs near the stairs.','迷宫般的改造可能让初次到访者迷失方向，因此图书馆保留旧入口，并在楼梯旁设置标识。','The maze-like renovation could disorientate first-time visitors / so the library kept the old entrance / and installed signs near the stairs.','disorientate 是及物动词；could 后接原形。','复杂空间布局可能令访客辨不清方向。'),M('The numbered floor signs disorientated visitors by clearly identifying every corridor and exit.','The unmarked corridors disorientated visitors because no sign identified a route or exit.','清楚标示走廊和出口能帮助定位，不会使人迷向。'),[Q('disorientate',1,1,'To disorientate someone in a building is to?','make it difficult for them to find their way','give them a reliable floor plan','show them a clearly marked exit','disorientate 指使人迷失方向。'),Q('disorientate',2,1,'Which spelling may be used as a variant of disorient?','disorientate','disorienteer','disorientify','disorientate 是英语中的变体形式。'),Q('disorientate',3,1,'A confusing sequence of unfamiliar turns may?','disorientate a visitor','orientate a visitor perfectly','shorten the building','连续陌生转弯可能使访客迷路。'),Q('disorientate',4,1,'Clear arrows at every junction are designed to prevent?','disorientation','orientation','navigation','路标用于避免迷失方向。')]);
P('disorientated','disorientated 是 disorientate 的过去分词形容词，常见于英式英语，表示无法辨清方向、时间或当前状况。',C('disorientated.s1','突发情况','After waking in an unfamiliar hotel during a power cut, Nina felt disorientated until she found the window and checked the street outside.','停电时在陌生酒店醒来后，妮娜一时辨不清方向，直到找到窗户并查看外面的街道才恢复方位感。','After waking in an unfamiliar hotel during a power cut / Nina felt disorientated / until she found the window and checked the street outside.','feel + 形容词描述感受；until 引出状态结束的时点。','陌生环境与黑暗令她无法定位，符合 s1。'),M('The traveler felt disorientated because she recognized the hotel, knew the time, and followed the familiar corridor.','The traveler felt oriented because she recognized the hotel, knew the time, and followed the familiar corridor.','熟悉酒店、时间和走廊表明她定位清楚。'),[Q('disorientated',1,1,'A disorientated person may be unsure?','where they are or what is happening','how to spell a familiar name only','whether a finished task is complete','disorientated 指方向或情境认知混乱。'),Q('disorientated',2,1,'Which experience could leave a traveler disorientated?','waking suddenly in a dark, unfamiliar room','following signs through a familiar station','reading the time on a working clock','在陌生黑暗房间突然醒来容易迷茫。'),Q('disorientated',3,1,'In British usage, disorientated is the past participle of?','disorientate','disorder','disrespect','disorientated 是 disorientate 的分词。'),Q('disorientated',4,1,'Someone who feels disorientated may need?','clear signs or help identifying their location','more confusing directions','a louder alarm without explanation','清楚的方位提示有助于恢复定位。')]);
P('disorientation','disorientation 由 disorient 加 -ation 构成；orient 与拉丁语 oriens“东方、日出”相关，名词指对地点、时间或现实情境的迷茫。',C('disorientation.s1','医疗观察','The nurse recorded brief disorientation after the patient woke from anesthesia and checked that he could identify his name and location.','患者从麻醉中醒来后短暂迷茫，护士记录了这一情况，并确认他能说出姓名和所在地点。','The nurse recorded brief disorientation after the patient woke from anesthesia / and checked that he could identify his name and location.','disorientation 作不可数名词；check that 引导核实内容。','无法立刻确认身份与地点体现定向障碍。'),M('The patient’s disorientation was evident because he immediately named the date, place, and reason for his visit correctly.','The patient’s orientation was intact because he immediately named the date, place, and reason for his visit correctly.','正确说出时间地点和来由表明定向力完整。'),[Q('disorientation',1,1,'Disorientation is?','confusion about place, time, or situation','a clear sense of direction','a loss of hearing','disorientation 指地点、时间或情境上的迷茫。'),Q('disorientation',2,1,'A person with temporary disorientation may?','not know where they are just after waking','give their address and date accurately','recognize every street immediately','醒后不知道身处何处是暂时定向障碍的表现。'),Q('disorientation',3,1,'Which question helps assess orientation after surgery?','“Can you tell me your name and where you are?”','“What is your favorite color?”','“Do you prefer tea or coffee?”','姓名与地点问题可检查定向力。'),Q('disorientation',4,1,'The opposite of disorientation is?','orientation','confusion','bewilderment','orientation 指清楚定位和方向。')]);
P('disown','disown 由 dis-“否认、分离”与 own“承认归属”构成；own 经古英语 āgan“拥有”发展而来，动词指否认与某人、信念或行为有关。',C('disown.s1','公共声明','The artist publicly disowned the unsigned poster, explaining that its message did not represent her views and that she had not created it.','艺术家公开否认那张未署名海报与自己有关，说明其内容不代表她的观点，而且并非她创作。','The artist publicly disowned the unsigned poster / explaining that its message did not represent her views / and that she had not created it.','disown 是及物动词；explain 后接并列 that 从句。','她明确否认作品归属及观点关联，符合 s1。'),M('The author disowned the book by proudly confirming that she had written every page and endorsed its claims.','The author owned the book by proudly confirming that she had written every page and endorsed its claims.','确认创作并认可观点表示承认，而非否认关联。'),[Q('disown',1,1,'To disown a statement is to?','deny responsibility for or connection with it','repeat it as one’s own view','translate it into another language','disown 指否认与某事有关或负有责任。'),Q('disown',2,1,'A company disowns an advertisement when it says?','the advertisement was not authorized or does not represent it','it will pay to publish the same ad','the ad’s text is correctly spelled','否认授权或代表性属于 disown。'),Q('disown',3,1,'Which verb is closest to disown in this sentence: “He disowned the claim”?','repudiated','endorsed','invented','repudiate 表示公开否认。'),Q('disown',4,1,'A person who disowns a relative is saying?','they no longer accept that relationship','they have just met the relative','they are proud of the relative','disown 亲属表示不再承认或接受关系。')]);
P('disparage','disparage 源自古法语 desparagier“视为不相称、贬低”，与 parage“身份、等级”相关；动词指轻蔑地贬损或低估。',C('disparage.s2','职场评价','The director warned reviewers not to disparage junior staff in public, even when their first drafts needed substantial revision.','主管提醒评审者不要当众贬低初级员工，即使他们的初稿确实需要大幅修改。','The director warned reviewers not to disparage junior staff in public / even when their first drafts needed substantial revision.','disparage 是及物动词；warn sb not to do 表示提醒不要做某事。','当众轻蔑贬低员工，体现 scornful criticism 的 s2。'),M('The reviewer disparaged the proposal as worthless, then urged every agency to adopt it without changes.','The reviewer praised the proposal as valuable, then urged every agency to adopt it without changes.','称提案毫无价值却要求所有机构采用，前后评价矛盾；该语境应为称赞。'),[Q('disparage',1,2,'To disparage a colleague is to?','speak about them in a scornfully belittling way','give them detailed fair credit','ask them to explain an idea','disparage 指轻蔑地批评、贬低。'),Q('disparage',2,1,'A comment that disparages a local tradition suggests it is?','unimportant or of little value','worthy of careful preservation','identical to every other tradition','贬低即暗示其不重要或价值低。'),Q('disparage',3,2,'Which sentence uses disparage in its scornful sense?','He disparaged the volunteers as useless despite their work.','She thanked the volunteers for their time.','The volunteers received clear instructions.','称志愿者无用是轻蔑贬低。'),Q('disparage',4,1,'A fair critic can identify flaws without?','disparaging the people who made the work','discussing evidence','suggesting specific improvements','可以批评作品而不贬损作者。')]);
P('disparate','disparate 源自拉丁语 disparatus“分开的”，由 dis- 与 parare“准备、配对”词族构成；指性质迥异、难以比较或归类。',C('disparate.s1','跨学科研究','The project combined disparate sources—oral histories, satellite images, and shipping logs—to reconstruct the storm’s effects.','项目结合了性质迥异的资料——口述史、卫星图像和航运记录——来重建风暴影响。','The project combined disparate sources / oral histories, satellite images, and shipping logs / to reconstruct the storm’s effects.','disparate 修饰 sources；破折号后列举具体资料类型。','这些来源在形式、来源和内容上差异很大，符合“迥异的”义 s1。'),M('The two data sets were disparate because they contained the same values in the same order.','The two data sets were identical because they contained the same values in the same order.','内容和顺序完全相同表示 identical，不是 disparate。'),[Q('disparate',1,1,'Disparate things are?','very different in kind','exactly alike','arranged in alphabetical order','disparate 指性质迥异。'),Q('disparate',2,2,'A researcher gathers disparate evidence when the evidence?','consists of unlike items that are hard to group together','comes from one repeated measurement only','has been proven identical','不同类型且难归类的材料是 disparate evidence。'),Q('disparate',3,1,'Which pair is most disparate?','a medieval poem and a satellite temperature map','two copies of the same letter','two identical red pencils','诗歌与卫星温度图在性质上迥异。'),Q('disparate',4,1,'The closest opposite of disparate is?','similar','unlike','heterogeneous','similar 表示相似。')]);
P('dispel','dispel 源自拉丁语 dispellere，由 dis-“分开”与 pellere“驱赶”构成；可指消除恐惧/误解，也可指驱散雾、云或人群。',C('dispel.s2','天气变化','By midmorning, a warm breeze began to dispel the fog over the harbor, revealing the moored boats one by one.','到上午中段，暖风开始驱散港口上空的雾，停泊的船只一艘接一艘显现出来。','By midmorning / a warm breeze began to dispel the fog over the harbor / revealing the moored boats one by one.','dispel 是及物动词；reveal 分词说明雾散后的结果。','暖风使雾散去，体现驱散物理现象的 s2。'),M('The breeze dispelled the fog by making the harbor disappear beneath a thicker cloud.','The breeze thickened the fog, making the harbor disappear beneath a denser cloud.','使雾更浓是加重而非驱散；应改为 thickened。'),[Q('dispel',1,1,'To dispel a rumor is to?','make it go away by showing it is false','spread it to more people','turn it into a law','抽象义是消除谣言或误解。'),Q('dispel',2,2,'A breeze may dispel fog by?','driving it away so visibility improves','making the fog denser','turning it into rain immediately','风把雾吹散，使能见度改善。'),Q('dispel',3,1,'Which phrase is natural?','dispel doubts about the result','dispel into the result','dispel the result from of doubt','常见搭配是 dispel doubts。'),Q('dispel',4,1,'A teacher dispels confusion when she?','explains the rule that students misunderstood','adds three new unexplained rules','refuses to answer questions','解释学生误解的规则可消除困惑。')]);
P('dispensable','dispensable 由 dispense + -able 构成；dispense 源自拉丁语 dispensare“分配、管理”，现代形容词指非必需、可省去而无重大损失。',C('dispensable.s2','编辑删改','The editor removed a dispensable paragraph that repeated the same point, and the article remained clear without it.','编辑删掉了一段可有可无的重复内容，文章删后依然清楚。','The editor removed a dispensable paragraph / that repeated the same point / and the article remained clear without it.','dispensable 修饰 paragraph；that 引导定语从句说明可删原因。','删除后文章仍完整，说明这段并非必需。'),M('The emergency oxygen supply was dispensable because patients could not safely breathe without it.','The emergency oxygen supply was indispensable because patients could not safely breathe without it.','患者无法安全呼吸说明氧气必不可少，应用 indispensable。'),[Q('dispensable',1,1,'A dispensable item is?','not necessary and able to be omitted','essential in every situation','impossible to replace','dispensable 指非必需、可省略。'),Q('dispensable',2,2,'A paragraph is dispensable if removing it?','causes no serious loss to the text','makes the argument impossible to follow','removes the only evidence','删掉后不造成重要损失，说明它可有可无。'),Q('dispensable',3,1,'Which item is least likely to be dispensable during a fire evacuation?','a working exit route','a decorative banner','a duplicate poster','疏散通道不能随意省去，最不可或缺。'),Q('dispensable',4,1,'The opposite of dispensable is?','indispensable','optional','unneeded','indispensable 表示不可或缺。')]);
P('dispensation','dispensation 由 dispense 加 -ation 构成，源自拉丁语 dispensare“分配、管理”；可指免除规则的特许，也可指分发或制度安排。',C('dispensation.s1','法规例外','The board granted a dispensation allowing the historic theater to exceed the usual closing time during the annual festival.','委员会特许这家历史剧院在年度节庆期间超过通常闭馆时间。','The board granted a dispensation / allowing the historic theater to exceed the usual closing time / during the annual festival.','grant a dispensation 表示给予特许；allowing 分词说明特许内容。','规则被正式豁免一段时间，符合 s1。'),M('The school granted a dispensation from the uniform rule but required every student to wear the uniform exactly as usual.','The school granted no dispensation from the uniform rule and required every student to wear it as usual.','仍必须照常穿制服表示规则未获豁免。'),[Q('dispensation',1,1,'A dispensation from a rule is?','official permission not to follow it','a stricter penalty for breaking it','a copy of the rulebook','dispensation 可指正式豁免规则的许可。'),Q('dispensation',2,2,'The dispensation of food supplies means?','the distribution or handing out of supplies','the destruction of all food','permission to skip a meal','dispensation 也可指物资的分发。'),Q('dispensation',3,1,'A club asks for a dispensation when it wants?','an authorized exception to a requirement','a list of all members','a more expensive venue','申请 dispensation 是寻求获准的规则例外。'),Q('dispensation',4,1,'Which phrase fits the exemption sense?','grant a dispensation from the age limit','dispensation of a poem’s rhyme','disposition of an empty chair','常见结构 grant a dispensation from a rule。')]);
P('dispenser','dispenser 由 dispense 加施事者后缀 -er 构成；dispense 源自拉丁语 dispensare“分配”，名词可指自动出物的装置，也可指配药人员。',C('dispenser.s2','药房服务','The hospital dispenser checked the dosage label before handing the prepared medicine to the patient.','医院配药人员在把配好的药交给患者前核对了剂量标签。','The hospital dispenser checked the dosage label / before handing the prepared medicine / to the patient.','dispenser 作可数名词；hand A to B 表示把 A 交给 B。','此处是配发药物的人，符合 s2。'),M('The soap dispenser was a pharmacist who explained the prescription to the patient.','The medicine dispenser was a pharmacist who explained the prescription to the patient.','解释处方的药剂人员是人，不是装肥皂的机器；应避免把物义与人义混淆。'),[Q('dispenser',1,1,'A wall-mounted soap dispenser is?','a container or device that releases soap','a person who writes novels','a medical diagnosis','装置义指按需释放肥皂的容器。'),Q('dispenser',2,2,'A pharmacy dispenser helps by?','preparing and handing out medicine','repairing a vending machine','designing hospital buildings','人义 dispenser 指配制和发药人员。'),Q('dispenser',3,1,'Which item is a ticket dispenser?','a machine that issues tickets when requested','a person checking a passenger’s health','a printed timetable','自动发票设备是 ticket dispenser。'),Q('dispenser',4,2,'The dispenser checked the prescription before supplying tablets. Here dispenser is?','a person who prepares and gives out medicine','a box that releases soap','a customer buying a ticket','检查处方的是配药人员。')]);
P('dispersal','dispersal 由 disperse 加 -al 构成；disperse 源自拉丁语 dispergere“撒开”，名词可指把人或物散布开，也可指驱散人群。',C('dispersal.s2','集会管理','After repeated warnings, officers ordered the dispersal of the crowd blocking the emergency entrance.','多次警告后，警员命令堵住紧急入口的人群散开。','After repeated warnings / officers ordered the dispersal of the crowd / blocking the emergency entrance.','order the dispersal of + 群体；blocking 分词修饰 crowd。','人群被要求解散，符合驱散义 s2。'),M('The police ordered the crowd’s dispersal but instructed everyone to remain packed together at the entrance.','The police ordered the crowd’s dispersal and instructed people to move away from the entrance.','dispersal 意味着人群散开，不能又要求继续挤在一起。'),[Q('dispersal',1,1,'The dispersal of seeds means?','their spread over a wider area','their growth into one seed','their removal from a plant by burning only','种子 dispersal 是向更广范围传播。'),Q('dispersal',2,2,'The dispersal of a crowd is?','the breaking up and movement away of its members','the crowd’s arrival at a site','the organization of a queue','人群驱散即成员散开离去。'),Q('dispersal',3,1,'Wind helps the dispersal of pollen by?','carrying it away from the source','keeping it inside one flower','turning it into water','风可把花粉带离原处传播。'),Q('dispersal',4,1,'A dispersal order at a blocked entrance asks people to?','leave the area and spread out','gather more tightly','remain exactly where they are','驱散命令要求人群离开并散开。')]);
P('dispersion','dispersion 源自拉丁语 dispersio，来自 dispergere“撒开”；可指人、种子或光在空间中的散布，也可指统计分布的离散程度。',C('dispersion.s1','光学实验','A prism produces dispersion by separating white light into colors that bend by different amounts.','棱镜使白光发生色散，将其分成折射程度不同的各种颜色。','A prism produces dispersion / by separating white light into colors / that bend by different amounts.','dispersion 作不可数名词；by + 动名词说明产生方式。','白光被分散为不同颜色，符合光的散布义。'),M('The prism showed no dispersion because white light separated into a full rainbow of colors.','The prism showed dispersion because white light separated into a full rainbow of colors.','分成彩虹色正是光色散的表现。'),[Q('dispersion',1,1,'In optics, dispersion is the?','separation or spreading of light into its component colors','reflection of sound from a wall','conversion of light into gravity','棱镜色散把复合光分成组成颜色。'),Q('dispersion',2,1,'Seed dispersion helps a plant by?','spreading seeds away from the parent plant','keeping every seed in one fruit forever','preventing seeds from reaching soil','种子散布有助于远离母株、扩大范围。'),Q('dispersion',3,1,'A population with high statistical dispersion has values that?','are widely spread out','are all exactly identical','cannot be measured','高离散度表示数据值分布较散。'),Q('dispersion',4,1,'The verb related to dispersion is?','disperse','disprove','displease','dispersion 源自 disperse。')]);
P('dispirit','dispirit 由 dis- 与 spirit 构成；spirit 源自拉丁语 spiritus“呼吸、精神”，动词指使人失去勇气或兴致。',C('dispirit.s1','团队鼓励','Repeated equipment delays began to dispirit the volunteers, so the organizer explained the revised schedule and thanked them for staying.','设备一再延误开始让志愿者泄气，因此组织者说明了新日程，并感谢他们继续留下帮忙。','Repeated equipment delays began to dispirit the volunteers / so the organizer explained the revised schedule / and thanked them for staying.','dispirit 是及物动词；begin to 后接原形，so 引出安抚举措。','反复延误降低志愿者的热情与勇气，符合词义。'),M('The week of failures dispirited the crew, making everyone feel more hopeful and energetic.','The week of failures dispirited the crew, making everyone feel less hopeful and energetic.','dispirit 指令人泄气，结果应是更缺乏希望和活力。'),[Q('dispirit',1,1,'To dispirit a team is to?','lower its morale','give it new courage','change its uniforms','dispirit 指使人沮丧、泄气。'),Q('dispirit',2,1,'Which news might dispirit a candidate?','learning that the position has been cancelled','receiving an invitation to interview','hearing that the panel liked the application','职位取消的消息容易打击求职者。'),Q('dispirit',3,1,'Choose the closest synonym in “The setback dispirited us.”','demoralized','encouraged','organized','setback 让人泄气，即 demoralized。'),Q('dispirit',4,1,'A coach tries not to dispirit players by?','giving specific guidance after a loss','mocking each mistake','telling them effort never matters','具体建议能帮助队员而非打击士气。')]);
P('displacement','displacement 由 displace 加 -ment 构成，源自古法语 desplacer“移开”；可指某物取代另一物，也可指人被迫离开家园。',C('displacement.s2','灾害救援','The flood caused the displacement of hundreds of families, who moved into temporary shelters until repairs made their homes safe.','洪水迫使数百个家庭离开家园，他们搬入临时避难所，直到房屋修复到安全状态。','The flood caused the displacement of hundreds of families / who moved into temporary shelters / until repairs made their homes safe.','displacement of + 人群；who 引导定语从句修饰 families。','家庭被迫迁离住所，符合强迫离家义 s2。'),M('The flood caused no displacement because every family was forced to leave its home.','The flood caused displacement because every family was forced to leave its home.','被迫离家就是 displacement，不能说没有迁离。'),[Q('displacement',1,2,'The displacement of families by a flood means?','they were forced to leave their homes','they chose a new paint color','they received larger houses automatically','灾害迫使家庭迁离即 displacement。'),Q('displacement',2,1,'In physics, displacement describes?','a change in an object’s position','the object’s color','the temperature of its surface','物理学 displacement 指位置改变。'),Q('displacement',3,1,'A new machine causes displacement of workers when it?','takes over jobs people previously did','gives every worker a promotion','moves its factory sign','技术替代岗位会造成劳动力 displacement。'),Q('displacement',4,2,'Which report concerns humanitarian displacement?','families fleeing homes damaged by fighting','a train moving five meters on a track','a new brand replacing an old label','因冲突逃离家园属于人道迁离。')]);
P('disposable','disposable 由 dispose + -able 构成；dispose 经古法语源自拉丁语 disponere“安排”，可指一次性使用后丢弃的，也可指可自由支配的。',C('disposable.s2','个人预算','After paying rent and setting aside money for bills, she had little disposable income for travel or entertainment.','支付房租并预留账单费用后，她几乎没有可自由支配的收入用于旅行或娱乐。','After paying rent and setting aside money for bills / she had little disposable income / for travel or entertainment.','disposable income 指扣除必要支出后可自行安排的收入。','剩余收入可由个人选择如何使用，符合 s2。'),M('Their disposable cups were designed to be reused every day for many years.','Their reusable cups were designed to be used every day for many years.','可多年反复使用的是 reusable，而非一次性 disposable。'),[Q('disposable',1,1,'A disposable cup is intended to be?','used once or briefly and then thrown away','kept as a permanent family heirloom','repaired each week for decades','disposable 物品用后通常丢弃。'),Q('disposable',2,2,'Disposable income is?','money left for a person to use after necessary costs','the total amount of unpaid tax','cash that cannot be spent','可支配收入是必要开支后的可自由使用金额。'),Q('disposable',3,1,'Which item is designed as disposable?','a single-use medical glove','a washable steel spoon','a refillable water bottle','一次性医用手套设计为使用后丢弃。'),Q('disposable',4,1,'The opposite of a disposable container is a?','reusable container','paper receipt','temporary label','reusable 表示可反复使用。')]);
P('disposal','disposal 由 dispose 加 -al 构成；dispose 源自拉丁语 disponere“安排、处理”，可指废弃物处理，也见于 at one’s disposal“由某人支配”。',C('disposal.s1','废物管理','The safe disposal of used batteries matters because damaged cells can leak chemicals into soil and groundwater.','废旧电池的安全处理很重要，因为受损电芯可能把化学物质渗入土壤和地下水。','The safe disposal of used batteries matters / because damaged cells can leak chemicals / into soil and groundwater.','disposal of + 废弃物；because 引出处理必要性。','语境讨论丢弃和处置废物，符合 s1。'),M('The hospital arranged disposal of clinical waste by leaving sealed sharps in a public park.','The hospital arranged safe disposal of clinical waste through an approved collection service.','把医疗锐器留在公共场所是不安全弃置，不能称妥善 disposal。'),[Q('disposal',1,1,'Waste disposal is the process of?','getting rid of waste safely','making waste from new materials','sorting visitors into groups','disposal of waste 指废弃物的处理。'),Q('disposal',2,2,'If a car is at your disposal, it is?','available for you to use as you choose','scheduled to be destroyed','not allowed to be driven','at one’s disposal 表示可供某人支配使用。'),Q('disposal',3,1,'Which phrase concerns removing rubbish?','the disposal of household waste','the disposal of one’s free afternoon','the disposal of a committee vote','此处是名词 disposal of waste 的处理义。'),Q('disposal',4,1,'“The tools are at the technician’s disposal” means?','the technician may use the tools','the tools must be thrown away','the technician has sold them','at someone’s disposal 表示由其支配。')]);
P('disposed','disposed 是 dispose 的过去分词形容词，常用 be disposed to 表示倾向/愿意，也可由 be disposed toward 表示对某人持某种态度。',C('disposed.s1','合作意愿','The neighboring firm was disposed to share its testing equipment after the two managers agreed on a schedule and insurance terms.','两位经理就时间表和保险条款达成一致后，邻近公司愿意共享测试设备。','The neighboring firm was disposed to share its testing equipment / after the two managers agreed / on a schedule and insurance terms.','be disposed to + 动词原形表示愿意或倾向做某事。','公司愿意共享设备，符合 s1。'),M('She was disposed to help, but she refused every request and said she had no intention of assisting.','She was unwilling to help, refusing every request and saying she had no intention of assisting.','拒绝所有请求并无意协助说明不愿意，与 disposed to help 矛盾。'),[Q('disposed',1,1,'Someone disposed to help is?','willing or inclined to help','forbidden to help','unable to understand help','be disposed to 表示愿意或倾向。'),Q('disposed',2,2,'“She is well disposed toward her neighbors” means?','she has a favorable attitude toward them','she has arranged them in a row','she intends to sell her home','be disposed toward 可表示对某人抱有某种态度。'),Q('disposed',3,1,'Complete the natural pattern: disposed ___ accept the offer.','to','for at','on about','常用结构为 be disposed to do。'),Q('disposed',4,1,'A person disposed to caution is likely to?','tend to act carefully','seek every avoidable risk','refuse to consider consequences','disposed to caution 表示倾向谨慎。')]);
P('disproportionate','disproportionate 由 dis-、proportion 与 -ate 构成；proportion 经拉丁语 proportio 指比例，形容与相关数量或原因不相称。',C('disproportionate.s1','资源分配','The small rural clinic received a disproportionate share of the new equipment because it served patients from several remote villages.','这家小型乡村诊所获得了不成比例的较多新设备，因为它服务于几个偏远村庄的患者。','The small rural clinic received a disproportionate share of the new equipment / because it served patients / from several remote villages.','a disproportionate share 指与基准不相称的份额；because 说明需求理由。','相对诊所规模而言份额偏大，但由服务范围解释。'),M('A one-minute delay caused a disproportionate response: the office calmly noted it and changed nothing.','A one-minute delay caused a proportionate response: the office calmly noted it and changed nothing.','冷静记录且不采取额外行动是相称的回应。'),[Q('disproportionate',1,1,'A disproportionate cost is?','too large or small compared with a relevant factor','exactly equal to every other cost','impossible to calculate','disproportionate 指与相关数量不成比例。'),Q('disproportionate',2,1,'A penalty is disproportionate if?','it is far harsher than the offense warrants','it matches the seriousness of the offense','it is explained clearly','处罚远超行为严重程度即不相称。'),Q('disproportionate',3,1,'Which pairing is natural?','a disproportionate response to a minor error','a disproportionate response in equal measure only','disproportionate of the response','常见搭配 disproportionate response to。'),Q('disproportionate',4,1,'The closest opposite of disproportionate is?','proportionate','excessive','unequal','proportionate 表示相称。')]);
P('disproportionately','disproportionately 由 disproportionate 加副词后缀 -ly 构成；表示相对于相关群体、因素或规模而言不成比例地。',C('disproportionately.s1','公共卫生统计','The heat wave affected older adults disproportionately because many lived alone in buildings without reliable cooling.','热浪对老年人的影响尤为严重，因为许多人独居在缺乏可靠制冷的建筑中。','The heat wave affected older adults disproportionately / because many lived alone / in buildings without reliable cooling.','disproportionately 修饰 affected，说明影响程度与人口比例不相称。','风险群体承受的影响高于其人口占比，符合副词义。'),M('The disease affected every age group disproportionately, meaning it affected each group in exactly the same proportion.','The disease affected every age group equally, meaning it affected each group in exactly the same proportion.','比例完全相同应使用 equally/proportionally，非 disproportionately。'),[Q('disproportionately',1,1,'If one group is affected disproportionately, its impact is?','unequal relative to its share or a relevant comparison','exactly the same as every other group','impossible to observe','副词表示影响比例不均。'),Q('disproportionately',2,1,'A fine falls disproportionately heavily on low-income households when?','it takes a much larger share of their income','every household pays the same small fraction of income','no household receives a fine','相同罚款可能占低收入家庭收入更大比例。'),Q('disproportionately',3,1,'Which phrase is idiomatic?','disproportionately high costs','disproportionately to high costs','disproportionate high-costly','副词 disproportionately 修饰形容词 high。'),Q('disproportionately',4,1,'An analyst finding that one region bears most pollution relative to its population may say it is?','disproportionately affected','equally unaffected','proportionally identical by definition','相对于人口占比承受更多污染即受影响不成比例。')]);
P('disputable','disputable 由 dispute 加 -able 构成；dispute 源自拉丁语 disputare“衡量、讨论”，形容观点或事实并非确定、可以被质疑。',C('disputable.s1','研究结论','The report’s estimate remains disputable because its authors excluded two districts with incomplete records from the calculation.','该报告的估算仍有争议，因为作者计算时排除了两个记录不完整的地区。','The report’s estimate remains disputable / because its authors excluded two districts / with incomplete records from the calculation.','disputable 作表语形容词；because 给出可争议的理由。','关键数据被排除使估算可受到质疑，符合义项。'),M('The figure was indisputable because no evidence supported it and every source contradicted it.','The figure was disputable because no evidence supported it and every source contradicted it.','缺乏支持且与来源矛盾，说明结论显然可以质疑。'),[Q('disputable',1,1,'A disputable claim is?','open to challenge or disagreement','certain beyond any question','written in invisible ink','disputable 指可以质疑、争论的。'),Q('disputable',2,1,'An estimate may be disputable when?','important evidence was left out','all relevant records agree','its method is fully transparent and replicated','遗漏重要证据会使估算可争议。'),Q('disputable',3,1,'The opposite of disputable is?','indisputable','debatable','questionable','indisputable 表示无可争议。'),Q('disputable',4,1,'Which wording is cautious for a disputable result?','the result remains open to challenge','the result is certainly true in all cases','no one may examine the data','审慎表达应承认结论仍可受到质疑。')]);
P('disputation','disputation 由 dispute 加 -ation 构成，源自拉丁语 disputatio“讨论、论辩”，指争论行为或有组织的学术辩论。',C('disputation.s1','学术研讨','The disputation on climate policy required each student to defend a claim with evidence and answer objections from the opposing team.','气候政策学术辩论要求每名学生用证据支持主张，并回答对方团队提出的质疑。','The disputation on climate policy required each student / to defend a claim with evidence / and answer objections from the opposing team.','disputation on + 主题；require sb to do 表示要求某人做。','有规则、需论证并回应反驳的正式辩论符合义项。'),M('The disputation ended without discussion because both teams presented identical claims and asked no questions.','The meeting ended without disputation because both teams presented identical claims and asked no questions.','没有讨论或相互论辩就不构成 disputation。'),[Q('disputation',1,1,'An academic disputation is?','a formal argument in which claims are defended','a silent reading period','a list of library books','disputation 指辩论或正式学术论辩。'),Q('disputation',2,1,'During a disputation, speakers are expected to?','give reasons and respond to objections','avoid stating any claim','vote without hearing arguments','辩论者需提出理由并回应反对意见。'),Q('disputation',3,1,'Which phrase fits naturally?','a disputation over the interpretation','a disputation under to the interpretation','a disputation with interpretingly','disputation 常与 over/about/on 表示讨论主题。'),Q('disputation',4,1,'A disputation differs from a casual chat because it is usually?','structured around opposing arguments','silent and individual','only about choosing a restaurant','正式辩论围绕对立论点展开。')]);
P('disqualify','disqualify 由 dis- 与 qualify 构成；qualify 源自拉丁语 qualis“何种的”，既可指因违规取消资格，也可指使某物不再适用于用途。',C('disqualify.s2','专业资格','The missing safety certificate could disqualify the laboratory from handling the chemical, even though its staff had years of experience.','缺少安全证书可能使实验室不具备处理该化学品的资格，尽管员工经验丰富。','The missing safety certificate could disqualify the laboratory / from handling the chemical / even though its staff had years of experience.','disqualify A from + 动名词，表示使 A 不具备做某事的资格。','证书缺失让实验室不适合执行该任务，符合 s2。'),M('The missing licence did not disqualify the team, even though the rules barred every unlicensed entrant.','The missing licence disqualified the team because the rules barred every unlicensed entrant.','规则明确禁止无证人员参赛，因此缺证会使团队失去资格。'),[Q('disqualify',1,1,'An athlete may be disqualified from a race for?','breaking a rule that makes participation invalid','finishing within the rules','wearing an approved uniform','违规可能导致取消比赛资格。'),Q('disqualify',2,2,'A cracked container may be disqualified for storing medicine because it?','is unfit for that purpose','has a label','is made of glass','不适合储药的容器会被排除使用。'),Q('disqualify',3,1,'A common structure is “disqualify a player ___ the final.”','from','at to','of into','固定结构为 disqualify someone from an event。'),Q('disqualify',4,1,'Which action could disqualify a bidder?','submitting a required form after the deadline','meeting every published requirement','asking a permitted clarification question','错过强制截止日期可能导致失去竞标资格。')]);
P('disquiet','disquiet 由 dis- 与 quiet 构成；quiet 经古法语与拉丁语 quietus“安静、安宁”相关，disquiet 可作名词表示忧虑，也可作动词使人不安。',C('disquiet.s2','安全通报','The unexplained gap in the inspection log disquieted residents, who asked officials to publish the missing records.','检查日志中无法解释的空档令居民不安，他们要求官员公布缺失记录。','The unexplained gap in the inspection log disquieted residents / who asked officials / to publish the missing records.','disquiet 在此作及物动词；who 引导定语从句说明居民反应。','记录缺口引发担忧，体现使人焦虑义 s2。'),M('The warning disquieted no one, although every resident became anxious immediately after hearing it.','The warning disquieted residents, who became anxious immediately after hearing it.','听到警告后人人焦虑，说明警告使他们不安。'),[Q('disquiet',1,2,'To disquiet a community is to?','make its members anxious or worried','give everyone a quiet room','answer every concern fully','动词 disquiet 表示使人忧虑。'),Q('disquiet',2,1,'Public disquiet over a sudden closure is?','a feeling of anxiety about what may happen','a celebration of the closure','a measure of building height','名词义指对未来状况的担忧。'),Q('disquiet',3,1,'Which news may cause disquiet among residents?','officials cannot explain a dangerous water test result','the water test meets every safety standard','a community meeting has ended early','无法解释危险检测结果会让居民担忧。'),Q('disquiet',4,1,'The noun often appears in the pattern?','disquiet about the future','disquiet into the quiet','disquiet for by going','常用搭配是 disquiet about。')]);
P('disrepute','disrepute 由 dis- 与 repute“名声、声誉”构成；repute 源自拉丁语 reputare“考虑、评估”，disrepute 指公众尊重下降、名誉受损。',C('disrepute.s1','机构公信力','A series of falsified reports brought the testing agency into disrepute and prompted an independent review of its methods.','一系列伪造报告使检测机构声誉扫地，并促使外部机构独立审查其方法。','A series of falsified reports brought the testing agency into disrepute / and prompted an independent review / of its methods.','bring A into disrepute 是固定表达，表示使 A 名誉受损。','伪造报告损害公众对机构的尊重与信任。'),M('The forged reports brought the agency into disrepute, meaning the public trusted it more than before.','The forged reports damaged the agency’s reputation, meaning the public trusted it less than before.','into disrepute 意为名誉受损、信任下降，不是更受信任。'),[Q('disrepute',1,1,'A company in disrepute has?','lost public respect or trust','won a new award','become impossible to contact','disrepute 指声誉受损。'),Q('disrepute',2,1,'What could bring a laboratory into disrepute?','falsifying test results','publishing accurate methods','correcting a harmless typo','伪造结果会严重损害机构名声。'),Q('disrepute',3,1,'Complete the idiom: bring an organization ___ disrepute.','into','at','under of','固定表达是 bring into disrepute。'),Q('disrepute',4,1,'A firm’s disrepute is most closely related to its?','damaged reputation','daily opening hours','building dimensions','disrepute 与声誉受损相关。')]);
P('disrespectful','disrespectful 由 dis-、respect 与 -ful 构成，respect 源自拉丁语 respicere“回看、顾及”；可指不尊重某人，也可指违反场合礼仪。',C('disrespectful.s2','礼仪规范','It was disrespectful to answer a condolence call by laughing loudly and changing the subject before the family had finished speaking.','家属还没说完就大笑着转移话题，回应慰问电话时这样做很失礼。','It was disrespectful to answer a condolence call / by laughing loudly / and changing the subject before the family had finished speaking.','it is disrespectful to do；by + 动名词说明失礼行为。','在哀悼场合大笑打断违反情境礼仪，符合 s2。'),M('The student was respectful at the memorial because she mocked the speaker and interrupted each sentence.','The student was disrespectful at the memorial because she mocked the speaker and interrupted each sentence.','嘲笑发言者并不断打断是不尊重。'),[Q('disrespectful',1,1,'A disrespectful comment shows?','a lack of respect for someone','careful appreciation','a neutral fact with no tone','disrespectful 指表现出不尊重。'),Q('disrespectful',2,2,'An act can be disrespectful even without insulting words when it?','breaks the manners expected for that occasion','follows the event’s customs','shows quiet attention','某些行为即使无辱骂，也会违反场合礼仪。'),Q('disrespectful',3,1,'Which behavior is disrespectful at a memorial?','mocking a speaker while they share a memory','listening quietly','offering condolences','纪念仪式上嘲笑发言者很失礼。'),Q('disrespectful',4,1,'The opposite of disrespectful is?','respectful','rude','insulting','respectful 表示尊重。')]);
P('disruption','disruption 由 disrupt 加 -ion 构成；disrupt 源自拉丁语 disrumpere“撕裂”，可指事件中断正常运转，也可指组织或秩序瓦解。',C('disruption.s1','公共交通','A power failure caused major disruption to the rail service, leaving commuters waiting while crews restored the signals.','停电严重扰乱了铁路服务，通勤者只能等维修人员恢复信号。','A power failure caused major disruption to the rail service / leaving commuters waiting / while crews restored the signals.','cause disruption to + 系统；leaving 分词说明后果。','服务无法按常态运行，符合中断义 s1。'),M('The outage caused major disruption to the train service, although every train ran on time and no route was interrupted.','The outage caused no disruption to the train service; every train ran on time and no route was interrupted.','列车准点且线路不中断，与“铁路服务严重受扰”矛盾。'),[Q('disruption',1,1,'A disruption to a service is?','an event that stops it working normally','a routine improvement with no interruption','a printed copy of the timetable','disruption 指正常运转受中断。'),Q('disruption',2,2,'The disruption of an old social order refers to?','its breakup or major disturbance','a small schedule adjustment only','a ceremony honoring it','秩序或群体的瓦解属于 s2。'),Q('disruption',3,1,'Which event causes disruption to a school day?','a burst pipe closes several classrooms','a lesson begins at its scheduled time','students receive their usual books','管道破裂导致教室关闭，会扰乱校日安排。'),Q('disruption',4,1,'A common phrase is?','disruption to transport','disruption for the bus stop it','disruption at to commute','常用结构 disruption to a service/system。')]);
P('disruptive','disruptive 由 disrupt 加 -ive 构成；disrupt 源自拉丁语 disrumpere“撕裂”，可指妨碍正常活动，也可描述以新方式剧变行业的创新。',C('disruptive.s2','商业创新','The startup’s disruptive payment system let small shops accept online orders without buying expensive point-of-sale equipment.','这家初创公司的颠覆性支付系统让小商店无需购买昂贵的销售终端也能接受线上订单。','The startup’s disruptive payment system let small shops accept online orders / without buying expensive point-of-sale equipment.','disruptive 修饰 system；let + 宾语 + 动词原形。','新技术改变行业旧有进入门槛，体现创新变革义 s2。'),M('The disruptive system changed nothing in the market and preserved every old limitation exactly as before.','The conventional system changed nothing in the market and preserved every old limitation exactly as before.','没有改变市场且保留旧限制并非 disruptive innovation。'),[Q('disruptive',1,1,'A disruptive noise in class?','interrupts the lesson','helps everyone concentrate','signals that class is over in every case','普通义指妨碍正常活动。'),Q('disruptive',2,2,'A disruptive technology may?','change an industry by introducing a new way to serve users','make every existing practice unchanged','refer only to loud sound','创新义指以新方式重塑行业。'),Q('disruptive',3,1,'Which behavior is disruptive during a meeting?','repeatedly shouting over other speakers','waiting for one’s turn','taking notes quietly','反复盖过发言会妨碍会议进行。'),Q('disruptive',4,2,'A new low-cost service that transforms a market is called disruptive because it?','upends established ways of doing business','makes no difference to customers','merely repeats an old product unchanged','颠覆行业做法符合创新义。')]);
P('dissatisfaction','dissatisfaction 由 dis- 与 satisfaction 构成；satisfy 源自拉丁语 satisfacere“做得足够”，名词指需求、服务或预期未被满足时的不满。',C('dissatisfaction.s1','客户服务','Customer dissatisfaction rose after the support line stopped answering calls during the hours printed on the company’s website.','客服热线在官网公布的时段内停止接听后，客户不满增加。','Customer dissatisfaction rose / after the support line stopped answering calls / during the hours printed on the company’s website.','dissatisfaction 作不可数名词；after 引出不满加剧的原因。','服务未达到公开承诺的预期，造成不满。'),M('The survey found no dissatisfaction even though every respondent said the service had failed to meet basic needs.','The survey found widespread dissatisfaction because every respondent said the service had failed to meet basic needs.','所有人表示需求未满足说明存在普遍不满。'),[Q('dissatisfaction',1,1,'Dissatisfaction with a service is?','annoyance because expectations were not met','complete delight with every feature','uncertainty about its spelling','dissatisfaction 指预期未达成引起的不满。'),Q('dissatisfaction',2,1,'A survey may measure customer dissatisfaction by asking?','what problems made users unhappy','which color users prefer in a logo only','how many employees work in another company','询问问题与不满原因可衡量客户不满。'),Q('dissatisfaction',3,1,'Which phrase is natural?','dissatisfaction with the service','dissatisfaction to the service','dissatisfaction for servicing','常用搭配是 dissatisfaction with。'),Q('dissatisfaction',4,1,'A practical response to rising dissatisfaction is to?','identify and fix the unmet need','hide complaints from the team','raise prices without explanation','找出并修复未满足需求可回应不满。')]);
P('dissatisfied','dissatisfied 由 dis- 与 satisfied 构成，表示需求或期望未被满足；satisfy 最终来自拉丁语 satis“足够”。',C('dissatisfied.s1','维修结果','The tenant was dissatisfied with the repair because the leak returned the next morning and the contractor had not tested the pipe.','漏水第二天又出现，而且承包商没有测试水管，房客因此对维修结果不满意。','The tenant was dissatisfied with the repair / because the leak returned the next morning / and the contractor had not tested the pipe.','be dissatisfied with + 人/事；because 引出不满原因。','问题复发且未充分测试，未达到房客的修复预期。'),M('The tenant was dissatisfied with the repair, so she praised it as flawless and asked for no changes.','The tenant was satisfied with the repair, so she praised it as flawless and asked for no changes.','称维修完美且无需改动表示满意。'),[Q('dissatisfied',1,1,'A dissatisfied customer is?','not pleased with what was provided','fully content with the result','unable to make a purchase','dissatisfied 指不满意的。'),Q('dissatisfied',2,1,'Which tenant is dissatisfied with a repair?','one whose leak returns the next day','one whose problem is fixed and tested','one who has not reported any issue','漏水复发说明维修未达到预期。'),Q('dissatisfied',3,1,'A common pattern is “dissatisfied ___ the outcome.”','with','to about','in by','dissatisfied 通常与 with 搭配。'),Q('dissatisfied',4,1,'The opposite of dissatisfied is?','satisfied','unhappy','displeased','satisfied 表示满意。')]);
P('dissatisfy','dissatisfy 由 dis- 与 satisfy 构成，意为使人不满意；satisfy 源自拉丁语 satisfacere“做到足够、满足”。',C('dissatisfy.s1','产品体验','A brief battery life may dissatisfy travelers who need their phones to last through a full day of navigation.','电池续航短可能令需要手机导航一整天的旅客不满意。','A brief battery life may dissatisfy travelers / who need their phones to last / through a full day of navigation.','dissatisfy 是及物动词；who 引导定语从句修饰 travelers。','续航未满足导航需要，可能造成不满。'),M('The prompt repair dissatisfies the tenant because it fixed the leak quickly and permanently.','The delayed repair dissatisfies the tenant because the leak continued for several weeks.','迅速且永久修好通常会令房客满意，而不是不满。'),[Q('dissatisfy',1,1,'To dissatisfy a buyer is to?','leave the buyer unhappy with the product','meet every expectation fully','teach the buyer to repair it','dissatisfy 表示使消费者不满意。'),Q('dissatisfy',2,1,'A slow checkout may dissatisfy shoppers because it?','does not meet their expectation of convenient service','gives them a useful discount','processes every order instantly','结账慢与便捷服务预期不符。'),Q('dissatisfy',3,1,'Which verb is closest to dissatisfy?','displease','delight','satisfy','displease 意为使不快、不满意。'),Q('dissatisfy',4,1,'In “The delay dissatisfies passengers,” what causes the dissatisfaction?','the delay','the passengers','the destination','主语 the delay 是造成不满的原因。')]);
P('dissect','dissect 源自拉丁语 dissecare，由 dis-“分开”与 secare“切”构成；既指解剖动植物，也可指详细分析文本、想法或事件。',C('dissect.s2','文本分析','In class, the students dissected the speech’s argument, separating its evidence from the emotional language used to persuade listeners.','课堂上，学生拆解了演讲论证，把证据与用于说服听众的情绪化语言区分开。','In class / the students dissected the speech’s argument / separating its evidence from the emotional language used to persuade listeners.','dissect 是及物动词；现在分词说明分析时区分的内容。','此处是把论证细致拆分分析，符合比喻义 s2。'),M('The reviewer dissected the argument by refusing to examine any of its claims or evidence.','The reviewer ignored the argument by refusing to examine any of its claims or evidence.','拒绝分析论点不是 dissect；dissect 意为详细检查各部分。'),[Q('dissect',1,1,'A biology student dissects a specimen to?','cut it open and study its structure','make it grow faster','preserve its colors by painting','生物学解剖是切开并研究结构。'),Q('dissect',2,2,'To dissect a novel in a review is to?','analyze its parts in detail','cut the printed pages with a knife','summarize only the author’s biography','比喻义指细致分析作品。'),Q('dissect',3,1,'Which task uses dissect figuratively?','examining each step in a flawed proof','opening a seed pod in a lab','slicing a loaf of bread','逐步分析证明属于比喻义。'),Q('dissect',4,2,'A critic dissects a policy by?','breaking down its assumptions, evidence, and effects','refusing to read it','measuring the paper it is printed on','分析政策的组成和影响即 dissect。')]);
P('dissemble','dissemble 源自古法语 dissembler，最终与拉丁语 dissimulare“伪装、隐藏”相关；指掩饰真实感受/计划，也可指假装不知道或不在意。',C('dissemble.s2','谈判策略','When asked whether he had read the confidential offer, the negotiator dissembled and pretended that the document was unfamiliar.','被问到是否读过保密报价时，谈判者佯装不知，假装不认识那份文件。','When asked whether he had read the confidential offer / the negotiator dissembled / and pretended that the document was unfamiliar.','dissemble 是不及物动词；pretend that 引导假装的内容。','他假装不知情而掩盖真实认知，符合 s2。'),M('She dissembled by openly stating her real plan and showing every private note to the team.','She was candid by openly stating her real plan and showing every private note to the team.','公开说明真实计划属于坦率，并非掩饰。'),[Q('dissemble',1,1,'To dissemble is to?','hide one’s true feelings or intentions','state every intention plainly','assemble a group for a meeting','dissemble 指掩饰真实情感或计划。'),Q('dissemble',2,2,'A witness dissembles when he?','pretends not to know or care about something','admits exactly what he remembers','asks for a glass of water','此处是佯装不知道或不在意。'),Q('dissemble',3,1,'Which behavior is dissembling?','smiling as if unconcerned while secretly fearing the result','openly telling the group about one’s worry','asking a direct question','表面装作不担心、实际隐藏情绪是 dissemble。'),Q('dissemble',4,1,'The closest opposite of dissemble is?','be candid','conceal','feign','坦率地说出真实想法与掩饰相反。')]);

})();
